INSERT INTO `schema_backups` (`id`, `created_by`, `source`, `sql`, `size_bytes`, `created_at`) VALUES
('0bc62cca-77a5-4699-880f-53266714683b', NULL, 'auto', '-- Schema dump (public) gerado em 2026-06-04 03:00:00.024961+00\n-- Apenas DDL. Não inclui dados.\n\n-- =====================\n-- ENUMS\n-- =====================\nCREATE TYPE public.app_role AS ENUM (\'admin\', \'user\');\nCREATE TYPE public.campaign_status AS ENUM (\'draft\', \'queued\', \'running\', \'done\', \'failed\', \'cancelled\');\nCREATE TYPE public.message_status AS ENUM (\'pending\', \'sending\', \'sent\', \'delivered\', \'read\', \'failed\');\nCREATE TYPE public.message_type AS ENUM (\'template\', \'text\', \'media\', \'interactive\');\nCREATE TYPE public.template_status AS ENUM (\'APPROVED\', \'PENDING\', \'REJECTED\', \'PAUSED\', \'DISABLED\');\n\n-- =====================\n-- TABELAS\n-- =====================\n\nCREATE TABLE public.audit_logs (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid,\n  actor_email text,\n  action text NOT NULL,\n  entity_type text,\n  entity_id text,\n  metadata jsonb NOT NULL DEFAULT \'{}\'::jsonb,\n  ip text,\n  user_agent text,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT audit_logs_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.campaign_messages (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL,\n  campaign_id uuid NOT NULL,\n  contact_id uuid,\n  to_phone text NOT NULL,\n  status message_status NOT NULL DEFAULT \'pending\'::message_status,\n  wa_message_id text,\n  error jsonb,\n  attempts integer NOT NULL DEFAULT 0,\n  sent_at timestamp with time zone,\n  delivered_at timestamp with time zone,\n  read_at timestamp with time zone,\n  failed_at timestamp with time zone,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\n  pricing_billable boolean,\n  pricing_category text,\n  pricing_model text,\n  conversation_id text,\n  conversation_origin text,\\n  CONSTRAINT campaign_messages_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.campaigns (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL,\n  name text NOT NULL,\n  message_type message_type NOT NULL,\n  template_id uuid,\n  list_id uuid,\n  payload jsonb NOT NULL DEFAULT \'{}\'::jsonb,\n  status campaign_status NOT NULL DEFAULT \'draft\'::campaign_status,\n  scheduled_at timestamp with time zone,\n  started_at timestamp with time zone,\n  finished_at timestamp with time zone,\n  totals jsonb NOT NULL DEFAULT \'{\"read\": 0, \"sent\": 0, \"total\": 0, \"failed\": 0, \"pending\": 0, \"delivered\": 0}\'::jsonb,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\n  updated_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT campaigns_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.contact_tags (\n  contact_id uuid NOT NULL,\n  tag_id uuid NOT NULL,\n  user_id uuid NOT NULL,\\n  CONSTRAINT contact_tags_pkey PRIMARY KEY (contact_id, tag_id)\n);\n\nCREATE TABLE public.contacts (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL,\n  phone_e164 text NOT NULL,\n  name text,\n  email text,\n  custom_fields jsonb NOT NULL DEFAULT \'{}\'::jsonb,\n  opted_out boolean NOT NULL DEFAULT false,\n  source text,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\n  updated_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT contacts_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.list_contacts (\n  list_id uuid NOT NULL,\n  contact_id uuid NOT NULL,\n  user_id uuid NOT NULL,\n  added_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT list_contacts_pkey PRIMARY KEY (list_id, contact_id)\n);\n\nCREATE TABLE public.lists (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL,\n  name text NOT NULL,\n  description text,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT lists_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.platform_settings (\n  id smallint NOT NULL DEFAULT 1,\n  meta_app_id text,\n  meta_app_secret text,\n  meta_config_id text,\n  meta_graph_version text NOT NULL DEFAULT \'v20.0\'::text,\n  updated_at timestamp with time zone NOT NULL DEFAULT now(),\n  updated_by uuid,\n  head_tags text,\n  body_tags text,\n  cron_secret text,\\n  CONSTRAINT platform_settings_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.profiles (\n  id uuid NOT NULL,\n  display_name text,\n  email text,\n  whatsapp_phone_number_id text,\n  whatsapp_waba_id text,\n  whatsapp_business_phone text,\n  api_key text NOT NULL DEFAULT encode(extensions.gen_random_bytes(24), \'hex\'::text),\n  rate_limit_per_second integer NOT NULL DEFAULT 20,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\n  updated_at timestamp with time zone NOT NULL DEFAULT now(),\n  whatsapp_access_token text,\n  whatsapp_app_secret text,\n  whatsapp_verify_token text,\n  meta_graph_version text NOT NULL DEFAULT \'v20.0\'::text,\n  avatar_url text,\n  full_name text,\n  phone text,\n  company_name text,\n  company_document text,\n  company_website text,\n  company_address text,\\n  CONSTRAINT profiles_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.schema_backups (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\n  source text NOT NULL DEFAULT \'auto\'::text,\n  size_bytes integer NOT NULL DEFAULT 0,\n  sql text NOT NULL,\n  created_by uuid,\\n  CONSTRAINT schema_backups_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.tags (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL,\n  name text NOT NULL,\n  color text NOT NULL DEFAULT \'#25D366\'::text,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT tags_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.templates (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL,\n  meta_template_id text,\n  name text NOT NULL,\n  language text NOT NULL,\n  category text,\n  status template_status NOT NULL DEFAULT \'PENDING\'::template_status,\n  components jsonb NOT NULL DEFAULT \'[]\'::jsonb,\n  synced_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT templates_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.user_roles (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL,\n  role app_role NOT NULL,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT user_roles_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.webhook_events (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  source text NOT NULL DEFAULT \'whatsapp\'::text,\n  raw jsonb NOT NULL,\n  processed boolean NOT NULL DEFAULT false,\n  received_at timestamp with time zone NOT NULL DEFAULT now(),\n  user_id uuid,\\n  CONSTRAINT webhook_events_pkey PRIMARY KEY (id)\n);\n\n-- =====================\n-- CONSTRAINTS (FK/UNIQUE/CHECK)\n-- =====================\nALTER TABLE public.audit_logs ADD CONSTRAINT audit_logs_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE SET NULL;\nALTER TABLE public.campaign_messages ADD CONSTRAINT campaign_messages_campaign_id_fkey FOREIGN KEY (campaign_id) REFERENCES campaigns(id) ON DELETE CASCADE;\nALTER TABLE public.campaign_messages ADD CONSTRAINT campaign_messages_contact_id_fkey FOREIGN KEY (contact_id) REFERENCES contacts(id) ON DELETE SET NULL;\nALTER TABLE public.campaign_messages ADD CONSTRAINT campaign_messages_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.campaigns ADD CONSTRAINT campaigns_list_id_fkey FOREIGN KEY (list_id) REFERENCES lists(id) ON DELETE SET NULL;\nALTER TABLE public.campaigns ADD CONSTRAINT campaigns_template_id_fkey FOREIGN KEY (template_id) REFERENCES templates(id) ON DELETE SET NULL;\nALTER TABLE public.campaigns ADD CONSTRAINT campaigns_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.contact_tags ADD CONSTRAINT contact_tags_contact_id_fkey FOREIGN KEY (contact_id) REFERENCES contacts(id) ON DELETE CASCADE;\nALTER TABLE public.contact_tags ADD CONSTRAINT contact_tags_tag_id_fkey FOREIGN KEY (tag_id) REFERENCES tags(id) ON DELETE CASCADE;\nALTER TABLE public.contact_tags ADD CONSTRAINT contact_tags_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.contacts ADD CONSTRAINT contacts_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.contacts ADD CONSTRAINT contacts_user_id_phone_e164_key UNIQUE (user_id, phone_e164);\nALTER TABLE public.list_contacts ADD CONSTRAINT list_contacts_contact_id_fkey FOREIGN KEY (contact_id) REFERENCES contacts(id) ON DELETE CASCADE;\nALTER TABLE public.list_contacts ADD CONSTRAINT list_contacts_list_id_fkey FOREIGN KEY (list_id) REFERENCES lists(id) ON DELETE CASCADE;\nALTER TABLE public.list_contacts ADD CONSTRAINT list_contacts_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.lists ADD CONSTRAINT lists_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.platform_settings ADD CONSTRAINT platform_settings_id_check CHECK ((id = 1));\nALTER TABLE public.platform_settings ADD CONSTRAINT platform_settings_updated_by_fkey FOREIGN KEY (updated_by) REFERENCES auth.users(id) ON DELETE SET NULL;\nALTER TABLE public.profiles ADD CONSTRAINT profiles_api_key_key UNIQUE (api_key);\nALTER TABLE public.profiles ADD CONSTRAINT profiles_id_fkey FOREIGN KEY (id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.tags ADD CONSTRAINT tags_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.tags ADD CONSTRAINT tags_user_id_name_key UNIQUE (user_id, name);\nALTER TABLE public.templates ADD CONSTRAINT templates_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.templates ADD CONSTRAINT templates_user_id_name_language_key UNIQUE (user_id, name, language);\nALTER TABLE public.user_roles ADD CONSTRAINT user_roles_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.user_roles ADD CONSTRAINT user_roles_user_id_role_key UNIQUE (user_id, role);\n\n-- =====================\n-- ÍNDICES\n-- =====================\nCREATE INDEX audit_logs_action_idx ON public.audit_logs USING btree (action);\nCREATE INDEX audit_logs_created_idx ON public.audit_logs USING btree (created_at DESC);\nCREATE INDEX audit_logs_user_idx ON public.audit_logs USING btree (user_id, created_at DESC);\nCREATE INDEX cm_pending_idx ON public.campaign_messages USING btree (campaign_id, status);\nCREATE INDEX cm_user_idx ON public.campaign_messages USING btree (user_id, status);\nCREATE INDEX cm_wa_id_idx ON public.campaign_messages USING btree (wa_message_id);\nCREATE INDEX idx_campaign_messages_billing ON public.campaign_messages USING btree (user_id, created_at DESC, pricing_category);\nCREATE INDEX idx_campaign_messages_status_updated ON public.campaign_messages USING btree (status, sent_at);\nCREATE INDEX contacts_user_idx ON public.contacts USING btree (user_id);\nCREATE INDEX list_contacts_list_idx ON public.list_contacts USING btree (list_id);\nCREATE INDEX idx_schema_backups_created_at ON public.schema_backups USING btree (created_at DESC);\nCREATE INDEX idx_webhook_events_received_at ON public.webhook_events USING btree (received_at);\nCREATE INDEX webhook_events_user_id_received_at_idx ON public.webhook_events USING btree (user_id, received_at DESC);\n\n-- =====================\n-- ROW LEVEL SECURITY\n-- =====================\nALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.campaign_messages ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.campaigns ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.contact_tags ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.contacts ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.list_contacts ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.lists ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.platform_settings ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.schema_backups ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.tags ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.templates ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.webhook_events ENABLE ROW LEVEL SECURITY;\n\n-- Policies\nCREATE POLICY audit_logs_no_delete ON public.audit_logs AS RESTRICTIVE FOR DELETE TO anon, authenticated USING (false);\nCREATE POLICY audit_logs_no_update ON public.audit_logs AS RESTRICTIVE FOR UPDATE TO anon, authenticated USING (false);\nCREATE POLICY audit_logs_no_write ON public.audit_logs AS RESTRICTIVE FOR INSERT TO anon, authenticated WITH CHECK (false);\nCREATE POLICY audit_logs_select_own_or_admin ON public.audit_logs AS PERMISSIVE FOR SELECT TO authenticated USING (((auth.uid() = user_id) OR has_role(auth.uid(), \'admin\'::app_role)));\nCREATE POLICY cm_delete_own ON public.campaign_messages AS PERMISSIVE FOR DELETE TO authenticated USING ((auth.uid() = user_id));\nCREATE POLICY cm_insert_own ON public.campaign_messages AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY cm_select_own ON public.campaign_messages AS PERMISSIVE FOR SELECT TO authenticated USING ((auth.uid() = user_id));\nCREATE POLICY cm_update_own ON public.campaign_messages AS PERMISSIVE FOR UPDATE TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY campaigns_all_own ON public.campaigns AS PERMISSIVE FOR ALL TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY contact_tags_all_own ON public.contact_tags AS PERMISSIVE FOR ALL TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY contacts_all_own ON public.contacts AS PERMISSIVE FOR ALL TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY list_contacts_all_own ON public.list_contacts AS PERMISSIVE FOR ALL TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY lists_all_own ON public.lists AS PERMISSIVE FOR ALL TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY platform_settings_admin_select ON public.platform_settings AS PERMISSIVE FOR SELECT TO authenticated USING (has_role(auth.uid(), \'admin\'::app_role));\nCREATE POLICY platform_settings_admin_update ON public.platform_settings AS PERMISSIVE FOR UPDATE TO authenticated USING (has_role(auth.uid(), \'admin\'::app_role)) WITH CHECK (has_role(auth.uid(), \'admin\'::app_role));\nCREATE POLICY profiles_insert_own ON public.profiles AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK ((auth.uid() = id));\nCREATE POLICY profiles_select_own ON public.profiles AS PERMISSIVE FOR SELECT TO authenticated USING ((auth.uid() = id));\nCREATE POLICY profiles_update_own ON public.profiles AS PERMISSIVE FOR UPDATE TO authenticated USING ((auth.uid() = id)) WITH CHECK ((auth.uid() = id));\nCREATE POLICY schema_backups_admin_delete ON public.schema_backups AS PERMISSIVE FOR DELETE TO authenticated USING (has_role(auth.uid(), \'admin\'::app_role));\nCREATE POLICY schema_backups_admin_insert ON public.schema_backups AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (has_role(auth.uid(), \'admin\'::app_role));\nCREATE POLICY schema_backups_admin_select ON public.schema_backups AS PERMISSIVE FOR SELECT TO authenticated USING (has_role(auth.uid(), \'admin\'::app_role));\nCREATE POLICY tags_all_own ON public.tags AS PERMISSIVE FOR ALL TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY templates_all_own ON public.templates AS PERMISSIVE FOR ALL TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY user_roles_admin_manage ON public.user_roles AS PERMISSIVE FOR ALL TO authenticated USING (has_role(auth.uid(), \'admin\'::app_role)) WITH CHECK (has_role(auth.uid(), \'admin\'::app_role));\nCREATE POLICY user_roles_block_self_delete ON public.user_roles AS RESTRICTIVE FOR DELETE TO authenticated USING ((user_id <> auth.uid()));\nCREATE POLICY user_roles_block_self_insert ON public.user_roles AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK ((user_id <> auth.uid()));\nCREATE POLICY user_roles_block_self_update ON public.user_roles AS RESTRICTIVE FOR UPDATE TO authenticated USING ((user_id <> auth.uid())) WITH CHECK ((user_id <> auth.uid()));\nCREATE POLICY user_roles_select_own ON public.user_roles AS PERMISSIVE FOR SELECT TO authenticated USING (((auth.uid() = user_id) OR has_role(auth.uid(), \'admin\'::app_role)));\nCREATE POLICY webhook_events_no_delete ON public.webhook_events AS RESTRICTIVE FOR DELETE TO anon, authenticated USING (false);\nCREATE POLICY webhook_events_no_insert ON public.webhook_events AS RESTRICTIVE FOR INSERT TO anon, authenticated WITH CHECK (false);\nCREATE POLICY webhook_events_no_update ON public.webhook_events AS RESTRICTIVE FOR UPDATE TO anon, authenticated USING (false) WITH CHECK (false);\nCREATE POLICY webhook_events_select_own ON public.webhook_events AS PERMISSIVE FOR SELECT TO authenticated USING ((auth.uid() = user_id));\n\n-- =====================\n-- FUNÇÕES\n-- =====================\nCREATE OR REPLACE FUNCTION public.assign_default_role()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO \'public\'\nAS $function$\nDECLARE\n  has_any_admin boolean;\nBEGIN\n  SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE role = \'admin\') INTO has_any_admin;\n  IF NOT has_any_admin THEN\n    INSERT INTO public.user_roles (user_id, role) VALUES (NEW.id, \'admin\')\n      ON CONFLICT DO NOTHING;\n  ELSE\n    INSERT INTO public.user_roles (user_id, role) VALUES (NEW.id, \'user\')\n      ON CONFLICT DO NOTHING;\n  END IF;\n  RETURN NEW;\nEND;\n$function$\n;\n\nCREATE OR REPLACE FUNCTION public.create_schema_backup(_source text DEFAULT \'auto\'::text, _user uuid DEFAULT NULL::uuid)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO \'public\', \'pg_catalog\'\nAS $function$\nDECLARE\n  dump text;\n  new_id uuid;\nBEGIN\n  -- Gera o dump (a função export_schema_sql exige admin; aqui contornamos por se rodar via cron/service_role)\n  -- Por isso replicamos a chamada interna como SECURITY DEFINER e pulamos o has_role quando _user é NULL (cron).\n  IF _user IS NOT NULL AND NOT public.has_role(_user, \'admin\') THEN\n    RAISE EXCEPTION \'forbidden\';\n  END IF;\n\n  -- Chama a função existente como superuser deste DEFINER\n  EXECUTE \'SELECT public.export_schema_sql_internal()\' INTO dump;\n\n  INSERT INTO public.schema_backups (source, size_bytes, sql, created_by)\n  VALUES (COALESCE(_source, \'auto\'), COALESCE(length(dump), 0), COALESCE(dump, \'\'), _user)\n  RETURNING id INTO new_id;\n\n  -- Mantém apenas as 30 versões mais recentes\n  DELETE FROM public.schema_backups\n   WHERE id IN (\n     SELECT id FROM public.schema_backups\n      ORDER BY created_at DESC OFFSET 30\n   );\n\n  RETURN new_id;\nEND;\n$function$\n;\n\nCREATE OR REPLACE FUNCTION public.cron_create_schema_backup()\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO \'public\', \'pg_catalog\'\nAS $function$\nBEGIN\n  PERFORM public.create_schema_backup(\'auto\', NULL);\nEND;\n$function$\n;\n\nCREATE OR REPLACE FUNCTION public.export_schema_sql()\n RETURNS text\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO \'public\', \'pg_catalog\'\nAS $function$\nDECLARE\n  out_sql text := \'\';\n  r record;\n  cols text;\n  pk text;\n  policy_cmd text;\nBEGIN\n  -- Apenas admins\n  IF NOT public.has_role(auth.uid(), \'admin\') THEN\n    RAISE EXCEPTION \'forbidden\';\n  END IF;\n\n  out_sql := \'-- Schema dump (public) gerado em \' || now()::text || E\'\\n\';\n  out_sql := out_sql || E\'-- Apenas DDL. Não inclui dados.\\n\\n\';\n\n  -- 1) ENUMS\n  out_sql := out_sql || E\'-- =====================\\n-- ENUMS\\n-- =====================\\n\';\n  FOR r IN\n    SELECT n.nspname, t.typname,\n           string_agg(quote_literal(e.enumlabel), \', \' ORDER BY e.enumsortorder) AS labels\n    FROM pg_type t\n    JOIN pg_enum e ON e.enumtypid = t.oid\n    JOIN pg_namespace n ON n.oid = t.typnamespace\n    WHERE n.nspname = \'public\'\n    GROUP BY n.nspname, t.typname\n    ORDER BY t.typname\n  LOOP\n    out_sql := out_sql || format(E\'CREATE TYPE %I.%I AS ENUM (%s);\\n\', r.nspname, r.typname, r.labels);\n  END LOOP;\n  out_sql := out_sql || E\'\\n\';\n\n  -- 2) TABELAS + COLUNAS + PK\n  out_sql := out_sql || E\'-- =====================\\n-- TABELAS\\n-- =====================\\n\';\n  FOR r IN\n    SELECT c.oid, c.relname\n    FROM pg_class c\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname = \'public\' AND c.relkind = \'r\'\n    ORDER BY c.relname\n  LOOP\n    -- colunas\n    SELECT string_agg(\n      format(\'  %I %s%s%s\',\n        a.attname,\n        format_type(a.atttypid, a.atttypmod),\n        CASE WHEN a.attnotnull THEN \' NOT NULL\' ELSE \'\' END,\n        CASE WHEN ad.adbin IS NOT NULL\n             THEN \' DEFAULT \' || pg_get_expr(ad.adbin, ad.adrelid)\n             ELSE \'\' END\n      ), E\',\\n\' ORDER BY a.attnum\n    )\n    INTO cols\n    FROM pg_attribute a\n    LEFT JOIN pg_attrdef ad ON ad.adrelid = a.attrelid AND ad.adnum = a.attnum\n    WHERE a.attrelid = r.oid AND a.attnum > 0 AND NOT a.attisdropped;\n\n    -- PK\n    SELECT format(\',\\n  CONSTRAINT %I PRIMARY KEY (%s)\',\n      con.conname,\n      (SELECT string_agg(quote_ident(att.attname), \', \' ORDER BY array_position(con.conkey, att.attnum))\n         FROM pg_attribute att\n        WHERE att.attrelid = r.oid AND att.attnum = ANY(con.conkey)))\n    INTO pk\n    FROM pg_constraint con\n    WHERE con.conrelid = r.oid AND con.contype = \'p\'\n    LIMIT 1;\n\n    out_sql := out_sql || format(E\'\\nCREATE TABLE public.%I (\\n%s%s\\n);\\n\',\n      r.relname, cols, COALESCE(pk, \'\'));\n  END LOOP;\n\n  -- 3) FK / UNIQUE / CHECK constraints (separados, depois de todas as tabelas)\n  out_sql := out_sql || E\'\\n-- =====================\\n-- CONSTRAINTS (FK/UNIQUE/CHECK)\\n-- =====================\\n\';\n  FOR r IN\n    SELECT c.relname AS table_name, con.conname,\n           pg_get_constraintdef(con.oid) AS def\n    FROM pg_constraint con\n    JOIN pg_class c ON c.oid = con.conrelid\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname = \'public\' AND con.contype IN (\'f\',\'u\',\'c\')\n    ORDER BY c.relname, con.conname\n  LOOP\n    out_sql := out_sql || format(E\'ALTER TABLE public.%I ADD CONSTRAINT %I %s;\\n\',\n      r.table_name, r.conname, r.def);\n  END LOOP;\n\n  -- 4) ÍNDICES (não-PK / não-unique-constraint)\n  out_sql := out_sql || E\'\\n-- =====================\\n-- ÍNDICES\\n-- =====================\\n\';\n  FOR r IN\n    SELECT indexdef\n    FROM pg_indexes\n    WHERE schemaname = \'public\'\n      AND indexname NOT IN (\n        SELECT conname FROM pg_constraint WHERE contype IN (\'p\',\'u\')\n      )\n    ORDER BY tablename, indexname\n  LOOP\n    out_sql := out_sql || r.indexdef || E\';\\n\';\n  END LOOP;\n\n  -- 5) RLS + POLICIES\n  out_sql := out_sql || E\'\\n-- =====================\\n-- ROW LEVEL SECURITY\\n-- =====================\\n\';\n  FOR r IN\n    SELECT c.relname\n    FROM pg_class c\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname=\'public\' AND c.relkind=\'r\' AND c.relrowsecurity\n    ORDER BY c.relname\n  LOOP\n    out_sql := out_sql || format(E\'ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY;\\n\', r.relname);\n  END LOOP;\n\n  out_sql := out_sql || E\'\\n-- Policies\\n\';\n  FOR r IN\n    SELECT schemaname, tablename, policyname, permissive, roles, cmd, qual, with_check\n    FROM pg_policies\n    WHERE schemaname=\'public\'\n    ORDER BY tablename, policyname\n  LOOP\n    policy_cmd := format(\'CREATE POLICY %I ON public.%I AS %s FOR %s TO %s\',\n      r.policyname, r.tablename,\n      COALESCE(r.permissive,\'PERMISSIVE\'),\n      r.cmd,\n      array_to_string(r.roles, \', \'));\n    IF r.qual IS NOT NULL THEN\n      policy_cmd := policy_cmd || \' USING (\' || r.qual || \')\';\n    END IF;\n    IF r.with_check IS NOT NULL THEN\n      policy_cmd := policy_cmd || \' WITH CHECK (\' || r.with_check || \')\';\n    END IF;\n    out_sql := out_sql || policy_cmd || E\';\\n\';\n  END LOOP;\n\n  -- 6) FUNÇÕES\n  out_sql := out_sql || E\'\\n-- =====================\\n-- FUNÇÕES\\n-- =====================\\n\';\n  FOR r IN\n    SELECT pg_get_functiondef(p.oid) AS def\n    FROM pg_proc p\n    JOIN pg_namespace n ON n.oid = p.pronamespace\n    WHERE n.nspname=\'public\' AND p.prokind = \'f\'\n    ORDER BY p.proname\n  LOOP\n    out_sql := out_sql || r.def || E\';\\n\\n\';\n  END LOOP;\n\n  -- 7) TRIGGERS\n  out_sql := out_sql || E\'-- =====================\\n-- TRIGGERS\\n-- =====================\\n\';\n  FOR r IN\n    SELECT pg_get_triggerdef(t.oid) AS def\n    FROM pg_trigger t\n    JOIN pg_class c ON c.oid = t.tgrelid\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname=\'public\' AND NOT t.tgisinternal\n    ORDER BY c.relname, t.tgname\n  LOOP\n    out_sql := out_sql || r.def || E\';\\n\';\n  END LOOP;\n\n  RETURN out_sql;\nEND;\n$function$\n;\n\nCREATE OR REPLACE FUNCTION public.export_schema_sql_internal()\n RETURNS text\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO \'public\', \'pg_catalog\'\nAS $function$\nDECLARE\n  out_sql text := \'\';\n  r record;\n  cols text;\n  pk text;\n  policy_cmd text;\nBEGIN\n  out_sql := \'-- Schema dump (public) gerado em \' || now()::text || E\'\\n\';\n  out_sql := out_sql || E\'-- Apenas DDL. Não inclui dados.\\n\\n\';\n\n  out_sql := out_sql || E\'-- =====================\\n-- ENUMS\\n-- =====================\\n\';\n  FOR r IN\n    SELECT n.nspname, t.typname,\n           string_agg(quote_literal(e.enumlabel), \', \' ORDER BY e.enumsortorder) AS labels\n    FROM pg_type t\n    JOIN pg_enum e ON e.enumtypid = t.oid\n    JOIN pg_namespace n ON n.oid = t.typnamespace\n    WHERE n.nspname = \'public\'\n    GROUP BY n.nspname, t.typname\n    ORDER BY t.typname\n  LOOP\n    out_sql := out_sql || format(E\'CREATE TYPE %I.%I AS ENUM (%s);\\n\', r.nspname, r.typname, r.labels);\n  END LOOP;\n  out_sql := out_sql || E\'\\n\';\n\n  out_sql := out_sql || E\'-- =====================\\n-- TABELAS\\n-- =====================\\n\';\n  FOR r IN\n    SELECT c.oid, c.relname\n    FROM pg_class c\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname = \'public\' AND c.relkind = \'r\'\n    ORDER BY c.relname\n  LOOP\n    SELECT string_agg(\n      format(\'  %I %s%s%s\',\n        a.attname,\n        format_type(a.atttypid, a.atttypmod),\n        CASE WHEN a.attnotnull THEN \' NOT NULL\' ELSE \'\' END,\n        CASE WHEN ad.adbin IS NOT NULL\n             THEN \' DEFAULT \' || pg_get_expr(ad.adbin, ad.adrelid)\n             ELSE \'\' END\n      ), E\',\\n\' ORDER BY a.attnum\n    )\n    INTO cols\n    FROM pg_attribute a\n    LEFT JOIN pg_attrdef ad ON ad.adrelid = a.attrelid AND ad.adnum = a.attnum\n    WHERE a.attrelid = r.oid AND a.attnum > 0 AND NOT a.attisdropped;\n\n    SELECT format(\',\\n  CONSTRAINT %I PRIMARY KEY (%s)\',\n      con.conname,\n      (SELECT string_agg(quote_ident(att.attname), \', \' ORDER BY array_position(con.conkey, att.attnum))\n         FROM pg_attribute att\n        WHERE att.attrelid = r.oid AND att.attnum = ANY(con.conkey)))\n    INTO pk\n    FROM pg_constraint con\n    WHERE con.conrelid = r.oid AND con.contype = \'p\'\n    LIMIT 1;\n\n    out_sql := out_sql || format(E\'\\nCREATE TABLE public.%I (\\n%s%s\\n);\\n\',\n      r.relname, cols, COALESCE(pk, \'\'));\n  END LOOP;\n\n  out_sql := out_sql || E\'\\n-- =====================\\n-- CONSTRAINTS (FK/UNIQUE/CHECK)\\n-- =====================\\n\';\n  FOR r IN\n    SELECT c.relname AS table_name, con.conname,\n           pg_get_constraintdef(con.oid) AS def\n    FROM pg_constraint con\n    JOIN pg_class c ON c.oid = con.conrelid\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname = \'public\' AND con.contype IN (\'f\',\'u\',\'c\')\n    ORDER BY c.relname, con.conname\n  LOOP\n    out_sql := out_sql || format(E\'ALTER TABLE public.%I ADD CONSTRAINT %I %s;\\n\',\n      r.table_name, r.conname, r.def);\n  END LOOP;\n\n  out_sql := out_sql || E\'\\n-- =====================\\n-- ÍNDICES\\n-- =====================\\n\';\n  FOR r IN\n    SELECT indexdef\n    FROM pg_indexes\n    WHERE schemaname = \'public\'\n      AND indexname NOT IN (SELECT conname FROM pg_constraint WHERE contype IN (\'p\',\'u\'))\n    ORDER BY tablename, indexname\n  LOOP\n    out_sql := out_sql || r.indexdef || E\';\\n\';\n  END LOOP;\n\n  out_sql := out_sql || E\'\\n-- =====================\\n-- ROW LEVEL SECURITY\\n-- =====================\\n\';\n  FOR r IN\n    SELECT c.relname FROM pg_class c\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname=\'public\' AND c.relkind=\'r\' AND c.relrowsecurity\n    ORDER BY c.relname\n  LOOP\n    out_sql := out_sql || format(E\'ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY;\\n\', r.relname);\n  END LOOP;\n\n  out_sql := out_sql || E\'\\n-- Policies\\n\';\n  FOR r IN\n    SELECT schemaname, tablename, policyname, permissive, roles, cmd, qual, with_check\n    FROM pg_policies WHERE schemaname=\'public\' ORDER BY tablename, policyname\n  LOOP\n    policy_cmd := format(\'CREATE POLICY %I ON public.%I AS %s FOR %s TO %s\',\n      r.policyname, r.tablename, COALESCE(r.permissive,\'PERMISSIVE\'),\n      r.cmd, array_to_string(r.roles, \', \'));\n    IF r.qual IS NOT NULL THEN policy_cmd := policy_cmd || \' USING (\' || r.qual || \')\'; END IF;\n    IF r.with_check IS NOT NULL THEN policy_cmd := policy_cmd || \' WITH CHECK (\' || r.with_check || \')\'; END IF;\n    out_sql := out_sql || policy_cmd || E\';\\n\';\n  END LOOP;\n\n  out_sql := out_sql || E\'\\n-- =====================\\n-- FUNÇÕES\\n-- =====================\\n\';\n  FOR r IN\n    SELECT pg_get_functiondef(p.oid) AS def\n    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n    WHERE n.nspname=\'public\' AND p.prokind=\'f\' ORDER BY p.proname\n  LOOP\n    out_sql := out_sql || r.def || E\';\\n\\n\';\n  END LOOP;\n\n  out_sql := out_sql || E\'-- =====================\\n-- TRIGGERS\\n-- =====================\\n\';\n  FOR r IN\n    SELECT pg_get_triggerdef(t.oid) AS def\n    FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname=\'public\' AND NOT t.tgisinternal\n    ORDER BY c.relname, t.tgname\n  LOOP\n    out_sql := out_sql || r.def || E\';\\n\';\n  END LOOP;\n\n  RETURN out_sql;\nEND;\n$function$\n;\n\nCREATE OR REPLACE FUNCTION public.handle_new_user()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO \'public\'\nAS $function$\nbegin\n  insert into public.profiles (id, email, display_name)\n  values (new.id, new.email, coalesce(new.raw_user_meta_data->>\'display_name\', split_part(new.email,\'@\',1)));\n  return new;\nend;\n$function$\n;\n\nCREATE OR REPLACE FUNCTION public.has_role(_user_id uuid, _role app_role)\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO \'public\'\nAS $function$\n  SELECT EXISTS (\n    SELECT 1 FROM public.user_roles\n    WHERE user_id = _user_id AND role = _role\n  )\n$function$\n;\n\nCREATE OR REPLACE FUNCTION public.set_updated_at()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO \'public\'\nAS $function$\nbegin new.updated_at = now(); return new; end;\n$function$\n;\n\n-- =====================\n-- TRIGGERS\n-- =====================\nCREATE TRIGGER campaigns_updated BEFORE UPDATE ON public.campaigns FOR EACH ROW EXECUTE FUNCTION set_updated_at();\nCREATE TRIGGER contacts_updated BEFORE UPDATE ON public.contacts FOR EACH ROW EXECUTE FUNCTION set_updated_at();\nCREATE TRIGGER profiles_updated BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION set_updated_at();\n', 30910, '2026-06-04 03:00:00');
INSERT INTO `schema_backups` (`id`, `created_by`, `source`, `sql`, `size_bytes`, `created_at`) VALUES
('2029569c-8c08-41d7-a31c-ad8b1205a73b', NULL, 'auto', '-- Schema dump (public) gerado em 2026-06-01 03:00:00.020722+00\n-- Apenas DDL. Não inclui dados.\n\n-- =====================\n-- ENUMS\n-- =====================\nCREATE TYPE public.app_role AS ENUM (\'admin\', \'user\');\nCREATE TYPE public.campaign_status AS ENUM (\'draft\', \'queued\', \'running\', \'done\', \'failed\', \'cancelled\');\nCREATE TYPE public.message_status AS ENUM (\'pending\', \'sending\', \'sent\', \'delivered\', \'read\', \'failed\');\nCREATE TYPE public.message_type AS ENUM (\'template\', \'text\', \'media\', \'interactive\');\nCREATE TYPE public.template_status AS ENUM (\'APPROVED\', \'PENDING\', \'REJECTED\', \'PAUSED\', \'DISABLED\');\n\n-- =====================\n-- TABELAS\n-- =====================\n\nCREATE TABLE public.audit_logs (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid,\n  actor_email text,\n  action text NOT NULL,\n  entity_type text,\n  entity_id text,\n  metadata jsonb NOT NULL DEFAULT \'{}\'::jsonb,\n  ip text,\n  user_agent text,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT audit_logs_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.campaign_messages (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL,\n  campaign_id uuid NOT NULL,\n  contact_id uuid,\n  to_phone text NOT NULL,\n  status message_status NOT NULL DEFAULT \'pending\'::message_status,\n  wa_message_id text,\n  error jsonb,\n  attempts integer NOT NULL DEFAULT 0,\n  sent_at timestamp with time zone,\n  delivered_at timestamp with time zone,\n  read_at timestamp with time zone,\n  failed_at timestamp with time zone,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\n  pricing_billable boolean,\n  pricing_category text,\n  pricing_model text,\n  conversation_id text,\n  conversation_origin text,\\n  CONSTRAINT campaign_messages_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.campaigns (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL,\n  name text NOT NULL,\n  message_type message_type NOT NULL,\n  template_id uuid,\n  list_id uuid,\n  payload jsonb NOT NULL DEFAULT \'{}\'::jsonb,\n  status campaign_status NOT NULL DEFAULT \'draft\'::campaign_status,\n  scheduled_at timestamp with time zone,\n  started_at timestamp with time zone,\n  finished_at timestamp with time zone,\n  totals jsonb NOT NULL DEFAULT \'{\"read\": 0, \"sent\": 0, \"total\": 0, \"failed\": 0, \"pending\": 0, \"delivered\": 0}\'::jsonb,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\n  updated_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT campaigns_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.contact_tags (\n  contact_id uuid NOT NULL,\n  tag_id uuid NOT NULL,\n  user_id uuid NOT NULL,\\n  CONSTRAINT contact_tags_pkey PRIMARY KEY (contact_id, tag_id)\n);\n\nCREATE TABLE public.contacts (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL,\n  phone_e164 text NOT NULL,\n  name text,\n  email text,\n  custom_fields jsonb NOT NULL DEFAULT \'{}\'::jsonb,\n  opted_out boolean NOT NULL DEFAULT false,\n  source text,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\n  updated_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT contacts_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.list_contacts (\n  list_id uuid NOT NULL,\n  contact_id uuid NOT NULL,\n  user_id uuid NOT NULL,\n  added_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT list_contacts_pkey PRIMARY KEY (list_id, contact_id)\n);\n\nCREATE TABLE public.lists (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL,\n  name text NOT NULL,\n  description text,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT lists_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.platform_settings (\n  id smallint NOT NULL DEFAULT 1,\n  meta_app_id text,\n  meta_app_secret text,\n  meta_config_id text,\n  meta_graph_version text NOT NULL DEFAULT \'v20.0\'::text,\n  updated_at timestamp with time zone NOT NULL DEFAULT now(),\n  updated_by uuid,\n  head_tags text,\n  body_tags text,\n  cron_secret text,\\n  CONSTRAINT platform_settings_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.profiles (\n  id uuid NOT NULL,\n  display_name text,\n  email text,\n  whatsapp_phone_number_id text,\n  whatsapp_waba_id text,\n  whatsapp_business_phone text,\n  api_key text NOT NULL DEFAULT encode(extensions.gen_random_bytes(24), \'hex\'::text),\n  rate_limit_per_second integer NOT NULL DEFAULT 20,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\n  updated_at timestamp with time zone NOT NULL DEFAULT now(),\n  whatsapp_access_token text,\n  whatsapp_app_secret text,\n  whatsapp_verify_token text,\n  meta_graph_version text NOT NULL DEFAULT \'v20.0\'::text,\n  avatar_url text,\n  full_name text,\n  phone text,\n  company_name text,\n  company_document text,\n  company_website text,\n  company_address text,\\n  CONSTRAINT profiles_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.schema_backups (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\n  source text NOT NULL DEFAULT \'auto\'::text,\n  size_bytes integer NOT NULL DEFAULT 0,\n  sql text NOT NULL,\n  created_by uuid,\\n  CONSTRAINT schema_backups_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.tags (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL,\n  name text NOT NULL,\n  color text NOT NULL DEFAULT \'#25D366\'::text,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT tags_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.templates (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL,\n  meta_template_id text,\n  name text NOT NULL,\n  language text NOT NULL,\n  category text,\n  status template_status NOT NULL DEFAULT \'PENDING\'::template_status,\n  components jsonb NOT NULL DEFAULT \'[]\'::jsonb,\n  synced_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT templates_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.user_roles (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL,\n  role app_role NOT NULL,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT user_roles_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.webhook_events (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  source text NOT NULL DEFAULT \'whatsapp\'::text,\n  raw jsonb NOT NULL,\n  processed boolean NOT NULL DEFAULT false,\n  received_at timestamp with time zone NOT NULL DEFAULT now(),\n  user_id uuid,\\n  CONSTRAINT webhook_events_pkey PRIMARY KEY (id)\n);\n\n-- =====================\n-- CONSTRAINTS (FK/UNIQUE/CHECK)\n-- =====================\nALTER TABLE public.audit_logs ADD CONSTRAINT audit_logs_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE SET NULL;\nALTER TABLE public.campaign_messages ADD CONSTRAINT campaign_messages_campaign_id_fkey FOREIGN KEY (campaign_id) REFERENCES campaigns(id) ON DELETE CASCADE;\nALTER TABLE public.campaign_messages ADD CONSTRAINT campaign_messages_contact_id_fkey FOREIGN KEY (contact_id) REFERENCES contacts(id) ON DELETE SET NULL;\nALTER TABLE public.campaign_messages ADD CONSTRAINT campaign_messages_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.campaigns ADD CONSTRAINT campaigns_list_id_fkey FOREIGN KEY (list_id) REFERENCES lists(id) ON DELETE SET NULL;\nALTER TABLE public.campaigns ADD CONSTRAINT campaigns_template_id_fkey FOREIGN KEY (template_id) REFERENCES templates(id) ON DELETE SET NULL;\nALTER TABLE public.campaigns ADD CONSTRAINT campaigns_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.contact_tags ADD CONSTRAINT contact_tags_contact_id_fkey FOREIGN KEY (contact_id) REFERENCES contacts(id) ON DELETE CASCADE;\nALTER TABLE public.contact_tags ADD CONSTRAINT contact_tags_tag_id_fkey FOREIGN KEY (tag_id) REFERENCES tags(id) ON DELETE CASCADE;\nALTER TABLE public.contact_tags ADD CONSTRAINT contact_tags_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.contacts ADD CONSTRAINT contacts_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.contacts ADD CONSTRAINT contacts_user_id_phone_e164_key UNIQUE (user_id, phone_e164);\nALTER TABLE public.list_contacts ADD CONSTRAINT list_contacts_contact_id_fkey FOREIGN KEY (contact_id) REFERENCES contacts(id) ON DELETE CASCADE;\nALTER TABLE public.list_contacts ADD CONSTRAINT list_contacts_list_id_fkey FOREIGN KEY (list_id) REFERENCES lists(id) ON DELETE CASCADE;\nALTER TABLE public.list_contacts ADD CONSTRAINT list_contacts_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.lists ADD CONSTRAINT lists_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.platform_settings ADD CONSTRAINT platform_settings_id_check CHECK ((id = 1));\nALTER TABLE public.platform_settings ADD CONSTRAINT platform_settings_updated_by_fkey FOREIGN KEY (updated_by) REFERENCES auth.users(id) ON DELETE SET NULL;\nALTER TABLE public.profiles ADD CONSTRAINT profiles_api_key_key UNIQUE (api_key);\nALTER TABLE public.profiles ADD CONSTRAINT profiles_id_fkey FOREIGN KEY (id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.tags ADD CONSTRAINT tags_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.tags ADD CONSTRAINT tags_user_id_name_key UNIQUE (user_id, name);\nALTER TABLE public.templates ADD CONSTRAINT templates_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.templates ADD CONSTRAINT templates_user_id_name_language_key UNIQUE (user_id, name, language);\nALTER TABLE public.user_roles ADD CONSTRAINT user_roles_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.user_roles ADD CONSTRAINT user_roles_user_id_role_key UNIQUE (user_id, role);\n\n-- =====================\n-- ÍNDICES\n-- =====================\nCREATE INDEX audit_logs_action_idx ON public.audit_logs USING btree (action);\nCREATE INDEX audit_logs_created_idx ON public.audit_logs USING btree (created_at DESC);\nCREATE INDEX audit_logs_user_idx ON public.audit_logs USING btree (user_id, created_at DESC);\nCREATE INDEX cm_pending_idx ON public.campaign_messages USING btree (campaign_id, status);\nCREATE INDEX cm_user_idx ON public.campaign_messages USING btree (user_id, status);\nCREATE INDEX cm_wa_id_idx ON public.campaign_messages USING btree (wa_message_id);\nCREATE INDEX idx_campaign_messages_billing ON public.campaign_messages USING btree (user_id, created_at DESC, pricing_category);\nCREATE INDEX idx_campaign_messages_status_updated ON public.campaign_messages USING btree (status, sent_at);\nCREATE INDEX contacts_user_idx ON public.contacts USING btree (user_id);\nCREATE INDEX list_contacts_list_idx ON public.list_contacts USING btree (list_id);\nCREATE INDEX idx_schema_backups_created_at ON public.schema_backups USING btree (created_at DESC);\nCREATE INDEX idx_webhook_events_received_at ON public.webhook_events USING btree (received_at);\nCREATE INDEX webhook_events_user_id_received_at_idx ON public.webhook_events USING btree (user_id, received_at DESC);\n\n-- =====================\n-- ROW LEVEL SECURITY\n-- =====================\nALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.campaign_messages ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.campaigns ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.contact_tags ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.contacts ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.list_contacts ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.lists ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.platform_settings ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.schema_backups ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.tags ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.templates ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.webhook_events ENABLE ROW LEVEL SECURITY;\n\n-- Policies\nCREATE POLICY audit_logs_no_delete ON public.audit_logs AS RESTRICTIVE FOR DELETE TO anon, authenticated USING (false);\nCREATE POLICY audit_logs_no_update ON public.audit_logs AS RESTRICTIVE FOR UPDATE TO anon, authenticated USING (false);\nCREATE POLICY audit_logs_no_write ON public.audit_logs AS RESTRICTIVE FOR INSERT TO anon, authenticated WITH CHECK (false);\nCREATE POLICY audit_logs_select_own_or_admin ON public.audit_logs AS PERMISSIVE FOR SELECT TO authenticated USING (((auth.uid() = user_id) OR has_role(auth.uid(), \'admin\'::app_role)));\nCREATE POLICY cm_delete_own ON public.campaign_messages AS PERMISSIVE FOR DELETE TO authenticated USING ((auth.uid() = user_id));\nCREATE POLICY cm_insert_own ON public.campaign_messages AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY cm_select_own ON public.campaign_messages AS PERMISSIVE FOR SELECT TO authenticated USING ((auth.uid() = user_id));\nCREATE POLICY cm_update_own ON public.campaign_messages AS PERMISSIVE FOR UPDATE TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY campaigns_all_own ON public.campaigns AS PERMISSIVE FOR ALL TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY contact_tags_all_own ON public.contact_tags AS PERMISSIVE FOR ALL TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY contacts_all_own ON public.contacts AS PERMISSIVE FOR ALL TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY list_contacts_all_own ON public.list_contacts AS PERMISSIVE FOR ALL TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY lists_all_own ON public.lists AS PERMISSIVE FOR ALL TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY platform_settings_admin_select ON public.platform_settings AS PERMISSIVE FOR SELECT TO authenticated USING (has_role(auth.uid(), \'admin\'::app_role));\nCREATE POLICY platform_settings_admin_update ON public.platform_settings AS PERMISSIVE FOR UPDATE TO authenticated USING (has_role(auth.uid(), \'admin\'::app_role)) WITH CHECK (has_role(auth.uid(), \'admin\'::app_role));\nCREATE POLICY profiles_insert_own ON public.profiles AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK ((auth.uid() = id));\nCREATE POLICY profiles_select_own ON public.profiles AS PERMISSIVE FOR SELECT TO authenticated USING ((auth.uid() = id));\nCREATE POLICY profiles_update_own ON public.profiles AS PERMISSIVE FOR UPDATE TO authenticated USING ((auth.uid() = id)) WITH CHECK ((auth.uid() = id));\nCREATE POLICY schema_backups_admin_delete ON public.schema_backups AS PERMISSIVE FOR DELETE TO authenticated USING (has_role(auth.uid(), \'admin\'::app_role));\nCREATE POLICY schema_backups_admin_insert ON public.schema_backups AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (has_role(auth.uid(), \'admin\'::app_role));\nCREATE POLICY schema_backups_admin_select ON public.schema_backups AS PERMISSIVE FOR SELECT TO authenticated USING (has_role(auth.uid(), \'admin\'::app_role));\nCREATE POLICY tags_all_own ON public.tags AS PERMISSIVE FOR ALL TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY templates_all_own ON public.templates AS PERMISSIVE FOR ALL TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY user_roles_admin_manage ON public.user_roles AS PERMISSIVE FOR ALL TO authenticated USING (has_role(auth.uid(), \'admin\'::app_role)) WITH CHECK (has_role(auth.uid(), \'admin\'::app_role));\nCREATE POLICY user_roles_block_self_delete ON public.user_roles AS RESTRICTIVE FOR DELETE TO authenticated USING ((user_id <> auth.uid()));\nCREATE POLICY user_roles_block_self_insert ON public.user_roles AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK ((user_id <> auth.uid()));\nCREATE POLICY user_roles_block_self_update ON public.user_roles AS RESTRICTIVE FOR UPDATE TO authenticated USING ((user_id <> auth.uid())) WITH CHECK ((user_id <> auth.uid()));\nCREATE POLICY user_roles_select_own ON public.user_roles AS PERMISSIVE FOR SELECT TO authenticated USING (((auth.uid() = user_id) OR has_role(auth.uid(), \'admin\'::app_role)));\nCREATE POLICY webhook_events_no_delete ON public.webhook_events AS RESTRICTIVE FOR DELETE TO anon, authenticated USING (false);\nCREATE POLICY webhook_events_no_insert ON public.webhook_events AS RESTRICTIVE FOR INSERT TO anon, authenticated WITH CHECK (false);\nCREATE POLICY webhook_events_no_update ON public.webhook_events AS RESTRICTIVE FOR UPDATE TO anon, authenticated USING (false) WITH CHECK (false);\nCREATE POLICY webhook_events_select_own ON public.webhook_events AS PERMISSIVE FOR SELECT TO authenticated USING ((auth.uid() = user_id));\n\n-- =====================\n-- FUNÇÕES\n-- =====================\nCREATE OR REPLACE FUNCTION public.assign_default_role()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO \'public\'\nAS $function$\nDECLARE\n  has_any_admin boolean;\nBEGIN\n  SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE role = \'admin\') INTO has_any_admin;\n  IF NOT has_any_admin THEN\n    INSERT INTO public.user_roles (user_id, role) VALUES (NEW.id, \'admin\')\n      ON CONFLICT DO NOTHING;\n  ELSE\n    INSERT INTO public.user_roles (user_id, role) VALUES (NEW.id, \'user\')\n      ON CONFLICT DO NOTHING;\n  END IF;\n  RETURN NEW;\nEND;\n$function$\n;\n\nCREATE OR REPLACE FUNCTION public.create_schema_backup(_source text DEFAULT \'auto\'::text, _user uuid DEFAULT NULL::uuid)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO \'public\', \'pg_catalog\'\nAS $function$\nDECLARE\n  dump text;\n  new_id uuid;\nBEGIN\n  -- Gera o dump (a função export_schema_sql exige admin; aqui contornamos por se rodar via cron/service_role)\n  -- Por isso replicamos a chamada interna como SECURITY DEFINER e pulamos o has_role quando _user é NULL (cron).\n  IF _user IS NOT NULL AND NOT public.has_role(_user, \'admin\') THEN\n    RAISE EXCEPTION \'forbidden\';\n  END IF;\n\n  -- Chama a função existente como superuser deste DEFINER\n  EXECUTE \'SELECT public.export_schema_sql_internal()\' INTO dump;\n\n  INSERT INTO public.schema_backups (source, size_bytes, sql, created_by)\n  VALUES (COALESCE(_source, \'auto\'), COALESCE(length(dump), 0), COALESCE(dump, \'\'), _user)\n  RETURNING id INTO new_id;\n\n  -- Mantém apenas as 30 versões mais recentes\n  DELETE FROM public.schema_backups\n   WHERE id IN (\n     SELECT id FROM public.schema_backups\n      ORDER BY created_at DESC OFFSET 30\n   );\n\n  RETURN new_id;\nEND;\n$function$\n;\n\nCREATE OR REPLACE FUNCTION public.cron_create_schema_backup()\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO \'public\', \'pg_catalog\'\nAS $function$\nBEGIN\n  PERFORM public.create_schema_backup(\'auto\', NULL);\nEND;\n$function$\n;\n\nCREATE OR REPLACE FUNCTION public.export_schema_sql()\n RETURNS text\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO \'public\', \'pg_catalog\'\nAS $function$\nDECLARE\n  out_sql text := \'\';\n  r record;\n  cols text;\n  pk text;\n  policy_cmd text;\nBEGIN\n  -- Apenas admins\n  IF NOT public.has_role(auth.uid(), \'admin\') THEN\n    RAISE EXCEPTION \'forbidden\';\n  END IF;\n\n  out_sql := \'-- Schema dump (public) gerado em \' || now()::text || E\'\\n\';\n  out_sql := out_sql || E\'-- Apenas DDL. Não inclui dados.\\n\\n\';\n\n  -- 1) ENUMS\n  out_sql := out_sql || E\'-- =====================\\n-- ENUMS\\n-- =====================\\n\';\n  FOR r IN\n    SELECT n.nspname, t.typname,\n           string_agg(quote_literal(e.enumlabel), \', \' ORDER BY e.enumsortorder) AS labels\n    FROM pg_type t\n    JOIN pg_enum e ON e.enumtypid = t.oid\n    JOIN pg_namespace n ON n.oid = t.typnamespace\n    WHERE n.nspname = \'public\'\n    GROUP BY n.nspname, t.typname\n    ORDER BY t.typname\n  LOOP\n    out_sql := out_sql || format(E\'CREATE TYPE %I.%I AS ENUM (%s);\\n\', r.nspname, r.typname, r.labels);\n  END LOOP;\n  out_sql := out_sql || E\'\\n\';\n\n  -- 2) TABELAS + COLUNAS + PK\n  out_sql := out_sql || E\'-- =====================\\n-- TABELAS\\n-- =====================\\n\';\n  FOR r IN\n    SELECT c.oid, c.relname\n    FROM pg_class c\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname = \'public\' AND c.relkind = \'r\'\n    ORDER BY c.relname\n  LOOP\n    -- colunas\n    SELECT string_agg(\n      format(\'  %I %s%s%s\',\n        a.attname,\n        format_type(a.atttypid, a.atttypmod),\n        CASE WHEN a.attnotnull THEN \' NOT NULL\' ELSE \'\' END,\n        CASE WHEN ad.adbin IS NOT NULL\n             THEN \' DEFAULT \' || pg_get_expr(ad.adbin, ad.adrelid)\n             ELSE \'\' END\n      ), E\',\\n\' ORDER BY a.attnum\n    )\n    INTO cols\n    FROM pg_attribute a\n    LEFT JOIN pg_attrdef ad ON ad.adrelid = a.attrelid AND ad.adnum = a.attnum\n    WHERE a.attrelid = r.oid AND a.attnum > 0 AND NOT a.attisdropped;\n\n    -- PK\n    SELECT format(\',\\n  CONSTRAINT %I PRIMARY KEY (%s)\',\n      con.conname,\n      (SELECT string_agg(quote_ident(att.attname), \', \' ORDER BY array_position(con.conkey, att.attnum))\n         FROM pg_attribute att\n        WHERE att.attrelid = r.oid AND att.attnum = ANY(con.conkey)))\n    INTO pk\n    FROM pg_constraint con\n    WHERE con.conrelid = r.oid AND con.contype = \'p\'\n    LIMIT 1;\n\n    out_sql := out_sql || format(E\'\\nCREATE TABLE public.%I (\\n%s%s\\n);\\n\',\n      r.relname, cols, COALESCE(pk, \'\'));\n  END LOOP;\n\n  -- 3) FK / UNIQUE / CHECK constraints (separados, depois de todas as tabelas)\n  out_sql := out_sql || E\'\\n-- =====================\\n-- CONSTRAINTS (FK/UNIQUE/CHECK)\\n-- =====================\\n\';\n  FOR r IN\n    SELECT c.relname AS table_name, con.conname,\n           pg_get_constraintdef(con.oid) AS def\n    FROM pg_constraint con\n    JOIN pg_class c ON c.oid = con.conrelid\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname = \'public\' AND con.contype IN (\'f\',\'u\',\'c\')\n    ORDER BY c.relname, con.conname\n  LOOP\n    out_sql := out_sql || format(E\'ALTER TABLE public.%I ADD CONSTRAINT %I %s;\\n\',\n      r.table_name, r.conname, r.def);\n  END LOOP;\n\n  -- 4) ÍNDICES (não-PK / não-unique-constraint)\n  out_sql := out_sql || E\'\\n-- =====================\\n-- ÍNDICES\\n-- =====================\\n\';\n  FOR r IN\n    SELECT indexdef\n    FROM pg_indexes\n    WHERE schemaname = \'public\'\n      AND indexname NOT IN (\n        SELECT conname FROM pg_constraint WHERE contype IN (\'p\',\'u\')\n      )\n    ORDER BY tablename, indexname\n  LOOP\n    out_sql := out_sql || r.indexdef || E\';\\n\';\n  END LOOP;\n\n  -- 5) RLS + POLICIES\n  out_sql := out_sql || E\'\\n-- =====================\\n-- ROW LEVEL SECURITY\\n-- =====================\\n\';\n  FOR r IN\n    SELECT c.relname\n    FROM pg_class c\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname=\'public\' AND c.relkind=\'r\' AND c.relrowsecurity\n    ORDER BY c.relname\n  LOOP\n    out_sql := out_sql || format(E\'ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY;\\n\', r.relname);\n  END LOOP;\n\n  out_sql := out_sql || E\'\\n-- Policies\\n\';\n  FOR r IN\n    SELECT schemaname, tablename, policyname, permissive, roles, cmd, qual, with_check\n    FROM pg_policies\n    WHERE schemaname=\'public\'\n    ORDER BY tablename, policyname\n  LOOP\n    policy_cmd := format(\'CREATE POLICY %I ON public.%I AS %s FOR %s TO %s\',\n      r.policyname, r.tablename,\n      COALESCE(r.permissive,\'PERMISSIVE\'),\n      r.cmd,\n      array_to_string(r.roles, \', \'));\n    IF r.qual IS NOT NULL THEN\n      policy_cmd := policy_cmd || \' USING (\' || r.qual || \')\';\n    END IF;\n    IF r.with_check IS NOT NULL THEN\n      policy_cmd := policy_cmd || \' WITH CHECK (\' || r.with_check || \')\';\n    END IF;\n    out_sql := out_sql || policy_cmd || E\';\\n\';\n  END LOOP;\n\n  -- 6) FUNÇÕES\n  out_sql := out_sql || E\'\\n-- =====================\\n-- FUNÇÕES\\n-- =====================\\n\';\n  FOR r IN\n    SELECT pg_get_functiondef(p.oid) AS def\n    FROM pg_proc p\n    JOIN pg_namespace n ON n.oid = p.pronamespace\n    WHERE n.nspname=\'public\' AND p.prokind = \'f\'\n    ORDER BY p.proname\n  LOOP\n    out_sql := out_sql || r.def || E\';\\n\\n\';\n  END LOOP;\n\n  -- 7) TRIGGERS\n  out_sql := out_sql || E\'-- =====================\\n-- TRIGGERS\\n-- =====================\\n\';\n  FOR r IN\n    SELECT pg_get_triggerdef(t.oid) AS def\n    FROM pg_trigger t\n    JOIN pg_class c ON c.oid = t.tgrelid\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname=\'public\' AND NOT t.tgisinternal\n    ORDER BY c.relname, t.tgname\n  LOOP\n    out_sql := out_sql || r.def || E\';\\n\';\n  END LOOP;\n\n  RETURN out_sql;\nEND;\n$function$\n;\n\nCREATE OR REPLACE FUNCTION public.export_schema_sql_internal()\n RETURNS text\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO \'public\', \'pg_catalog\'\nAS $function$\nDECLARE\n  out_sql text := \'\';\n  r record;\n  cols text;\n  pk text;\n  policy_cmd text;\nBEGIN\n  out_sql := \'-- Schema dump (public) gerado em \' || now()::text || E\'\\n\';\n  out_sql := out_sql || E\'-- Apenas DDL. Não inclui dados.\\n\\n\';\n\n  out_sql := out_sql || E\'-- =====================\\n-- ENUMS\\n-- =====================\\n\';\n  FOR r IN\n    SELECT n.nspname, t.typname,\n           string_agg(quote_literal(e.enumlabel), \', \' ORDER BY e.enumsortorder) AS labels\n    FROM pg_type t\n    JOIN pg_enum e ON e.enumtypid = t.oid\n    JOIN pg_namespace n ON n.oid = t.typnamespace\n    WHERE n.nspname = \'public\'\n    GROUP BY n.nspname, t.typname\n    ORDER BY t.typname\n  LOOP\n    out_sql := out_sql || format(E\'CREATE TYPE %I.%I AS ENUM (%s);\\n\', r.nspname, r.typname, r.labels);\n  END LOOP;\n  out_sql := out_sql || E\'\\n\';\n\n  out_sql := out_sql || E\'-- =====================\\n-- TABELAS\\n-- =====================\\n\';\n  FOR r IN\n    SELECT c.oid, c.relname\n    FROM pg_class c\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname = \'public\' AND c.relkind = \'r\'\n    ORDER BY c.relname\n  LOOP\n    SELECT string_agg(\n      format(\'  %I %s%s%s\',\n        a.attname,\n        format_type(a.atttypid, a.atttypmod),\n        CASE WHEN a.attnotnull THEN \' NOT NULL\' ELSE \'\' END,\n        CASE WHEN ad.adbin IS NOT NULL\n             THEN \' DEFAULT \' || pg_get_expr(ad.adbin, ad.adrelid)\n             ELSE \'\' END\n      ), E\',\\n\' ORDER BY a.attnum\n    )\n    INTO cols\n    FROM pg_attribute a\n    LEFT JOIN pg_attrdef ad ON ad.adrelid = a.attrelid AND ad.adnum = a.attnum\n    WHERE a.attrelid = r.oid AND a.attnum > 0 AND NOT a.attisdropped;\n\n    SELECT format(\',\\n  CONSTRAINT %I PRIMARY KEY (%s)\',\n      con.conname,\n      (SELECT string_agg(quote_ident(att.attname), \', \' ORDER BY array_position(con.conkey, att.attnum))\n         FROM pg_attribute att\n        WHERE att.attrelid = r.oid AND att.attnum = ANY(con.conkey)))\n    INTO pk\n    FROM pg_constraint con\n    WHERE con.conrelid = r.oid AND con.contype = \'p\'\n    LIMIT 1;\n\n    out_sql := out_sql || format(E\'\\nCREATE TABLE public.%I (\\n%s%s\\n);\\n\',\n      r.relname, cols, COALESCE(pk, \'\'));\n  END LOOP;\n\n  out_sql := out_sql || E\'\\n-- =====================\\n-- CONSTRAINTS (FK/UNIQUE/CHECK)\\n-- =====================\\n\';\n  FOR r IN\n    SELECT c.relname AS table_name, con.conname,\n           pg_get_constraintdef(con.oid) AS def\n    FROM pg_constraint con\n    JOIN pg_class c ON c.oid = con.conrelid\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname = \'public\' AND con.contype IN (\'f\',\'u\',\'c\')\n    ORDER BY c.relname, con.conname\n  LOOP\n    out_sql := out_sql || format(E\'ALTER TABLE public.%I ADD CONSTRAINT %I %s;\\n\',\n      r.table_name, r.conname, r.def);\n  END LOOP;\n\n  out_sql := out_sql || E\'\\n-- =====================\\n-- ÍNDICES\\n-- =====================\\n\';\n  FOR r IN\n    SELECT indexdef\n    FROM pg_indexes\n    WHERE schemaname = \'public\'\n      AND indexname NOT IN (SELECT conname FROM pg_constraint WHERE contype IN (\'p\',\'u\'))\n    ORDER BY tablename, indexname\n  LOOP\n    out_sql := out_sql || r.indexdef || E\';\\n\';\n  END LOOP;\n\n  out_sql := out_sql || E\'\\n-- =====================\\n-- ROW LEVEL SECURITY\\n-- =====================\\n\';\n  FOR r IN\n    SELECT c.relname FROM pg_class c\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname=\'public\' AND c.relkind=\'r\' AND c.relrowsecurity\n    ORDER BY c.relname\n  LOOP\n    out_sql := out_sql || format(E\'ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY;\\n\', r.relname);\n  END LOOP;\n\n  out_sql := out_sql || E\'\\n-- Policies\\n\';\n  FOR r IN\n    SELECT schemaname, tablename, policyname, permissive, roles, cmd, qual, with_check\n    FROM pg_policies WHERE schemaname=\'public\' ORDER BY tablename, policyname\n  LOOP\n    policy_cmd := format(\'CREATE POLICY %I ON public.%I AS %s FOR %s TO %s\',\n      r.policyname, r.tablename, COALESCE(r.permissive,\'PERMISSIVE\'),\n      r.cmd, array_to_string(r.roles, \', \'));\n    IF r.qual IS NOT NULL THEN policy_cmd := policy_cmd || \' USING (\' || r.qual || \')\'; END IF;\n    IF r.with_check IS NOT NULL THEN policy_cmd := policy_cmd || \' WITH CHECK (\' || r.with_check || \')\'; END IF;\n    out_sql := out_sql || policy_cmd || E\';\\n\';\n  END LOOP;\n\n  out_sql := out_sql || E\'\\n-- =====================\\n-- FUNÇÕES\\n-- =====================\\n\';\n  FOR r IN\n    SELECT pg_get_functiondef(p.oid) AS def\n    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n    WHERE n.nspname=\'public\' AND p.prokind=\'f\' ORDER BY p.proname\n  LOOP\n    out_sql := out_sql || r.def || E\';\\n\\n\';\n  END LOOP;\n\n  out_sql := out_sql || E\'-- =====================\\n-- TRIGGERS\\n-- =====================\\n\';\n  FOR r IN\n    SELECT pg_get_triggerdef(t.oid) AS def\n    FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname=\'public\' AND NOT t.tgisinternal\n    ORDER BY c.relname, t.tgname\n  LOOP\n    out_sql := out_sql || r.def || E\';\\n\';\n  END LOOP;\n\n  RETURN out_sql;\nEND;\n$function$\n;\n\nCREATE OR REPLACE FUNCTION public.handle_new_user()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO \'public\'\nAS $function$\nbegin\n  insert into public.profiles (id, email, display_name)\n  values (new.id, new.email, coalesce(new.raw_user_meta_data->>\'display_name\', split_part(new.email,\'@\',1)));\n  return new;\nend;\n$function$\n;\n\nCREATE OR REPLACE FUNCTION public.has_role(_user_id uuid, _role app_role)\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO \'public\'\nAS $function$\n  SELECT EXISTS (\n    SELECT 1 FROM public.user_roles\n    WHERE user_id = _user_id AND role = _role\n  )\n$function$\n;\n\nCREATE OR REPLACE FUNCTION public.set_updated_at()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO \'public\'\nAS $function$\nbegin new.updated_at = now(); return new; end;\n$function$\n;\n\n-- =====================\n-- TRIGGERS\n-- =====================\nCREATE TRIGGER campaigns_updated BEFORE UPDATE ON public.campaigns FOR EACH ROW EXECUTE FUNCTION set_updated_at();\nCREATE TRIGGER contacts_updated BEFORE UPDATE ON public.contacts FOR EACH ROW EXECUTE FUNCTION set_updated_at();\nCREATE TRIGGER profiles_updated BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION set_updated_at();\n', 30910, '2026-06-01 03:00:00');
INSERT INTO `schema_backups` (`id`, `created_by`, `source`, `sql`, `size_bytes`, `created_at`) VALUES
('206cf96b-45fa-463a-abbe-e171cc5a4227', NULL, 'auto', '-- Schema dump (public) gerado em 2026-06-16 03:00:00.038265+00\n-- Apenas DDL. Não inclui dados.\n\n-- =====================\n-- ENUMS\n-- =====================\nCREATE TYPE public.app_role AS ENUM (\'admin\', \'user\');\nCREATE TYPE public.campaign_status AS ENUM (\'draft\', \'queued\', \'running\', \'done\', \'failed\', \'cancelled\');\nCREATE TYPE public.message_status AS ENUM (\'pending\', \'sending\', \'sent\', \'delivered\', \'read\', \'failed\');\nCREATE TYPE public.message_type AS ENUM (\'template\', \'text\', \'media\', \'interactive\');\nCREATE TYPE public.template_status AS ENUM (\'APPROVED\', \'PENDING\', \'REJECTED\', \'PAUSED\', \'DISABLED\');\n\n-- =====================\n-- TABELAS\n-- =====================\n\nCREATE TABLE public.audit_logs (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid,\n  actor_email text,\n  action text NOT NULL,\n  entity_type text,\n  entity_id text,\n  metadata jsonb NOT NULL DEFAULT \'{}\'::jsonb,\n  ip text,\n  user_agent text,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT audit_logs_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.campaign_messages (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL,\n  campaign_id uuid NOT NULL,\n  contact_id uuid,\n  to_phone text NOT NULL,\n  status message_status NOT NULL DEFAULT \'pending\'::message_status,\n  wa_message_id text,\n  error jsonb,\n  attempts integer NOT NULL DEFAULT 0,\n  sent_at timestamp with time zone,\n  delivered_at timestamp with time zone,\n  read_at timestamp with time zone,\n  failed_at timestamp with time zone,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\n  pricing_billable boolean,\n  pricing_category text,\n  pricing_model text,\n  conversation_id text,\n  conversation_origin text,\\n  CONSTRAINT campaign_messages_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.campaigns (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL,\n  name text NOT NULL,\n  message_type message_type NOT NULL,\n  template_id uuid,\n  list_id uuid,\n  payload jsonb NOT NULL DEFAULT \'{}\'::jsonb,\n  status campaign_status NOT NULL DEFAULT \'draft\'::campaign_status,\n  scheduled_at timestamp with time zone,\n  started_at timestamp with time zone,\n  finished_at timestamp with time zone,\n  totals jsonb NOT NULL DEFAULT \'{\"read\": 0, \"sent\": 0, \"total\": 0, \"failed\": 0, \"pending\": 0, \"delivered\": 0}\'::jsonb,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\n  updated_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT campaigns_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.contact_tags (\n  contact_id uuid NOT NULL,\n  tag_id uuid NOT NULL,\n  user_id uuid NOT NULL,\\n  CONSTRAINT contact_tags_pkey PRIMARY KEY (contact_id, tag_id)\n);\n\nCREATE TABLE public.contacts (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL,\n  phone_e164 text NOT NULL,\n  name text,\n  email text,\n  custom_fields jsonb NOT NULL DEFAULT \'{}\'::jsonb,\n  opted_out boolean NOT NULL DEFAULT false,\n  source text,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\n  updated_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT contacts_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.list_contacts (\n  list_id uuid NOT NULL,\n  contact_id uuid NOT NULL,\n  user_id uuid NOT NULL,\n  added_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT list_contacts_pkey PRIMARY KEY (list_id, contact_id)\n);\n\nCREATE TABLE public.lists (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL,\n  name text NOT NULL,\n  description text,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT lists_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.platform_settings (\n  id smallint NOT NULL DEFAULT 1,\n  meta_app_id text,\n  meta_app_secret text,\n  meta_config_id text,\n  meta_graph_version text NOT NULL DEFAULT \'v20.0\'::text,\n  updated_at timestamp with time zone NOT NULL DEFAULT now(),\n  updated_by uuid,\n  head_tags text,\n  body_tags text,\n  cron_secret text,\\n  CONSTRAINT platform_settings_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.profiles (\n  id uuid NOT NULL,\n  display_name text,\n  email text,\n  whatsapp_phone_number_id text,\n  whatsapp_waba_id text,\n  whatsapp_business_phone text,\n  api_key text NOT NULL DEFAULT encode(extensions.gen_random_bytes(24), \'hex\'::text),\n  rate_limit_per_second integer NOT NULL DEFAULT 20,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\n  updated_at timestamp with time zone NOT NULL DEFAULT now(),\n  whatsapp_access_token text,\n  whatsapp_app_secret text,\n  whatsapp_verify_token text,\n  meta_graph_version text NOT NULL DEFAULT \'v20.0\'::text,\n  avatar_url text,\n  full_name text,\n  phone text,\n  company_name text,\n  company_document text,\n  company_website text,\n  company_address text,\\n  CONSTRAINT profiles_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.schema_backups (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\n  source text NOT NULL DEFAULT \'auto\'::text,\n  size_bytes integer NOT NULL DEFAULT 0,\n  sql text NOT NULL,\n  created_by uuid,\\n  CONSTRAINT schema_backups_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.tags (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL,\n  name text NOT NULL,\n  color text NOT NULL DEFAULT \'#25D366\'::text,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT tags_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.templates (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL,\n  meta_template_id text,\n  name text NOT NULL,\n  language text NOT NULL,\n  category text,\n  status template_status NOT NULL DEFAULT \'PENDING\'::template_status,\n  components jsonb NOT NULL DEFAULT \'[]\'::jsonb,\n  synced_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT templates_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.user_roles (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL,\n  role app_role NOT NULL,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT user_roles_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.webhook_events (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  source text NOT NULL DEFAULT \'whatsapp\'::text,\n  raw jsonb NOT NULL,\n  processed boolean NOT NULL DEFAULT false,\n  received_at timestamp with time zone NOT NULL DEFAULT now(),\n  user_id uuid,\\n  CONSTRAINT webhook_events_pkey PRIMARY KEY (id)\n);\n\n-- =====================\n-- CONSTRAINTS (FK/UNIQUE/CHECK)\n-- =====================\nALTER TABLE public.audit_logs ADD CONSTRAINT audit_logs_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE SET NULL;\nALTER TABLE public.campaign_messages ADD CONSTRAINT campaign_messages_campaign_id_fkey FOREIGN KEY (campaign_id) REFERENCES campaigns(id) ON DELETE CASCADE;\nALTER TABLE public.campaign_messages ADD CONSTRAINT campaign_messages_contact_id_fkey FOREIGN KEY (contact_id) REFERENCES contacts(id) ON DELETE SET NULL;\nALTER TABLE public.campaign_messages ADD CONSTRAINT campaign_messages_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.campaigns ADD CONSTRAINT campaigns_list_id_fkey FOREIGN KEY (list_id) REFERENCES lists(id) ON DELETE SET NULL;\nALTER TABLE public.campaigns ADD CONSTRAINT campaigns_template_id_fkey FOREIGN KEY (template_id) REFERENCES templates(id) ON DELETE SET NULL;\nALTER TABLE public.campaigns ADD CONSTRAINT campaigns_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.contact_tags ADD CONSTRAINT contact_tags_contact_id_fkey FOREIGN KEY (contact_id) REFERENCES contacts(id) ON DELETE CASCADE;\nALTER TABLE public.contact_tags ADD CONSTRAINT contact_tags_tag_id_fkey FOREIGN KEY (tag_id) REFERENCES tags(id) ON DELETE CASCADE;\nALTER TABLE public.contact_tags ADD CONSTRAINT contact_tags_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.contacts ADD CONSTRAINT contacts_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.contacts ADD CONSTRAINT contacts_user_id_phone_e164_key UNIQUE (user_id, phone_e164);\nALTER TABLE public.list_contacts ADD CONSTRAINT list_contacts_contact_id_fkey FOREIGN KEY (contact_id) REFERENCES contacts(id) ON DELETE CASCADE;\nALTER TABLE public.list_contacts ADD CONSTRAINT list_contacts_list_id_fkey FOREIGN KEY (list_id) REFERENCES lists(id) ON DELETE CASCADE;\nALTER TABLE public.list_contacts ADD CONSTRAINT list_contacts_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.lists ADD CONSTRAINT lists_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.platform_settings ADD CONSTRAINT platform_settings_id_check CHECK ((id = 1));\nALTER TABLE public.platform_settings ADD CONSTRAINT platform_settings_updated_by_fkey FOREIGN KEY (updated_by) REFERENCES auth.users(id) ON DELETE SET NULL;\nALTER TABLE public.profiles ADD CONSTRAINT profiles_api_key_key UNIQUE (api_key);\nALTER TABLE public.profiles ADD CONSTRAINT profiles_id_fkey FOREIGN KEY (id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.tags ADD CONSTRAINT tags_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.tags ADD CONSTRAINT tags_user_id_name_key UNIQUE (user_id, name);\nALTER TABLE public.templates ADD CONSTRAINT templates_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.templates ADD CONSTRAINT templates_user_id_name_language_key UNIQUE (user_id, name, language);\nALTER TABLE public.user_roles ADD CONSTRAINT user_roles_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.user_roles ADD CONSTRAINT user_roles_user_id_role_key UNIQUE (user_id, role);\n\n-- =====================\n-- ÍNDICES\n-- =====================\nCREATE INDEX audit_logs_action_idx ON public.audit_logs USING btree (action);\nCREATE INDEX audit_logs_created_idx ON public.audit_logs USING btree (created_at DESC);\nCREATE INDEX audit_logs_user_idx ON public.audit_logs USING btree (user_id, created_at DESC);\nCREATE INDEX cm_pending_idx ON public.campaign_messages USING btree (campaign_id, status);\nCREATE INDEX cm_user_idx ON public.campaign_messages USING btree (user_id, status);\nCREATE INDEX cm_wa_id_idx ON public.campaign_messages USING btree (wa_message_id);\nCREATE INDEX idx_campaign_messages_billing ON public.campaign_messages USING btree (user_id, created_at DESC, pricing_category);\nCREATE INDEX idx_campaign_messages_status_updated ON public.campaign_messages USING btree (status, sent_at);\nCREATE INDEX contacts_user_idx ON public.contacts USING btree (user_id);\nCREATE INDEX list_contacts_list_idx ON public.list_contacts USING btree (list_id);\nCREATE INDEX idx_schema_backups_created_at ON public.schema_backups USING btree (created_at DESC);\nCREATE INDEX idx_webhook_events_received_at ON public.webhook_events USING btree (received_at);\nCREATE INDEX webhook_events_user_id_received_at_idx ON public.webhook_events USING btree (user_id, received_at DESC);\n\n-- =====================\n-- ROW LEVEL SECURITY\n-- =====================\nALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.campaign_messages ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.campaigns ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.contact_tags ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.contacts ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.list_contacts ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.lists ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.platform_settings ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.schema_backups ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.tags ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.templates ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.webhook_events ENABLE ROW LEVEL SECURITY;\n\n-- Policies\nCREATE POLICY audit_logs_no_delete ON public.audit_logs AS RESTRICTIVE FOR DELETE TO anon, authenticated USING (false);\nCREATE POLICY audit_logs_no_update ON public.audit_logs AS RESTRICTIVE FOR UPDATE TO anon, authenticated USING (false);\nCREATE POLICY audit_logs_no_write ON public.audit_logs AS RESTRICTIVE FOR INSERT TO anon, authenticated WITH CHECK (false);\nCREATE POLICY audit_logs_select_own_or_admin ON public.audit_logs AS PERMISSIVE FOR SELECT TO authenticated USING (((auth.uid() = user_id) OR has_role(auth.uid(), \'admin\'::app_role)));\nCREATE POLICY cm_delete_own ON public.campaign_messages AS PERMISSIVE FOR DELETE TO authenticated USING ((auth.uid() = user_id));\nCREATE POLICY cm_insert_own ON public.campaign_messages AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY cm_select_own ON public.campaign_messages AS PERMISSIVE FOR SELECT TO authenticated USING ((auth.uid() = user_id));\nCREATE POLICY cm_update_own ON public.campaign_messages AS PERMISSIVE FOR UPDATE TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY campaigns_all_own ON public.campaigns AS PERMISSIVE FOR ALL TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY contact_tags_all_own ON public.contact_tags AS PERMISSIVE FOR ALL TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY contacts_all_own ON public.contacts AS PERMISSIVE FOR ALL TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY list_contacts_all_own ON public.list_contacts AS PERMISSIVE FOR ALL TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY lists_all_own ON public.lists AS PERMISSIVE FOR ALL TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY platform_settings_admin_select ON public.platform_settings AS PERMISSIVE FOR SELECT TO authenticated USING (has_role(auth.uid(), \'admin\'::app_role));\nCREATE POLICY platform_settings_admin_update ON public.platform_settings AS PERMISSIVE FOR UPDATE TO authenticated USING (has_role(auth.uid(), \'admin\'::app_role)) WITH CHECK (has_role(auth.uid(), \'admin\'::app_role));\nCREATE POLICY profiles_insert_own ON public.profiles AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK ((auth.uid() = id));\nCREATE POLICY profiles_select_own ON public.profiles AS PERMISSIVE FOR SELECT TO authenticated USING ((auth.uid() = id));\nCREATE POLICY profiles_update_own ON public.profiles AS PERMISSIVE FOR UPDATE TO authenticated USING ((auth.uid() = id)) WITH CHECK ((auth.uid() = id));\nCREATE POLICY schema_backups_admin_delete ON public.schema_backups AS PERMISSIVE FOR DELETE TO authenticated USING (has_role(auth.uid(), \'admin\'::app_role));\nCREATE POLICY schema_backups_admin_insert ON public.schema_backups AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (has_role(auth.uid(), \'admin\'::app_role));\nCREATE POLICY schema_backups_admin_select ON public.schema_backups AS PERMISSIVE FOR SELECT TO authenticated USING (has_role(auth.uid(), \'admin\'::app_role));\nCREATE POLICY tags_all_own ON public.tags AS PERMISSIVE FOR ALL TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY templates_all_own ON public.templates AS PERMISSIVE FOR ALL TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY user_roles_admin_manage ON public.user_roles AS PERMISSIVE FOR ALL TO authenticated USING (has_role(auth.uid(), \'admin\'::app_role)) WITH CHECK (has_role(auth.uid(), \'admin\'::app_role));\nCREATE POLICY user_roles_block_self_delete ON public.user_roles AS RESTRICTIVE FOR DELETE TO authenticated USING ((user_id <> auth.uid()));\nCREATE POLICY user_roles_block_self_insert ON public.user_roles AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK ((user_id <> auth.uid()));\nCREATE POLICY user_roles_block_self_update ON public.user_roles AS RESTRICTIVE FOR UPDATE TO authenticated USING ((user_id <> auth.uid())) WITH CHECK ((user_id <> auth.uid()));\nCREATE POLICY user_roles_select_own ON public.user_roles AS PERMISSIVE FOR SELECT TO authenticated USING (((auth.uid() = user_id) OR has_role(auth.uid(), \'admin\'::app_role)));\nCREATE POLICY webhook_events_no_delete ON public.webhook_events AS RESTRICTIVE FOR DELETE TO anon, authenticated USING (false);\nCREATE POLICY webhook_events_no_insert ON public.webhook_events AS RESTRICTIVE FOR INSERT TO anon, authenticated WITH CHECK (false);\nCREATE POLICY webhook_events_no_update ON public.webhook_events AS RESTRICTIVE FOR UPDATE TO anon, authenticated USING (false) WITH CHECK (false);\nCREATE POLICY webhook_events_select_own ON public.webhook_events AS PERMISSIVE FOR SELECT TO authenticated USING ((auth.uid() = user_id));\n\n-- =====================\n-- FUNÇÕES\n-- =====================\nCREATE OR REPLACE FUNCTION public.assign_default_role()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO \'public\'\nAS $function$\nDECLARE\n  has_any_admin boolean;\nBEGIN\n  SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE role = \'admin\') INTO has_any_admin;\n  IF NOT has_any_admin THEN\n    INSERT INTO public.user_roles (user_id, role) VALUES (NEW.id, \'admin\')\n      ON CONFLICT DO NOTHING;\n  ELSE\n    INSERT INTO public.user_roles (user_id, role) VALUES (NEW.id, \'user\')\n      ON CONFLICT DO NOTHING;\n  END IF;\n  RETURN NEW;\nEND;\n$function$\n;\n\nCREATE OR REPLACE FUNCTION public.create_schema_backup(_source text DEFAULT \'auto\'::text, _user uuid DEFAULT NULL::uuid)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO \'public\', \'pg_catalog\'\nAS $function$\nDECLARE\n  dump text;\n  new_id uuid;\nBEGIN\n  -- Gera o dump (a função export_schema_sql exige admin; aqui contornamos por se rodar via cron/service_role)\n  -- Por isso replicamos a chamada interna como SECURITY DEFINER e pulamos o has_role quando _user é NULL (cron).\n  IF _user IS NOT NULL AND NOT public.has_role(_user, \'admin\') THEN\n    RAISE EXCEPTION \'forbidden\';\n  END IF;\n\n  -- Chama a função existente como superuser deste DEFINER\n  EXECUTE \'SELECT public.export_schema_sql_internal()\' INTO dump;\n\n  INSERT INTO public.schema_backups (source, size_bytes, sql, created_by)\n  VALUES (COALESCE(_source, \'auto\'), COALESCE(length(dump), 0), COALESCE(dump, \'\'), _user)\n  RETURNING id INTO new_id;\n\n  -- Mantém apenas as 30 versões mais recentes\n  DELETE FROM public.schema_backups\n   WHERE id IN (\n     SELECT id FROM public.schema_backups\n      ORDER BY created_at DESC OFFSET 30\n   );\n\n  RETURN new_id;\nEND;\n$function$\n;\n\nCREATE OR REPLACE FUNCTION public.cron_create_schema_backup()\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO \'public\', \'pg_catalog\'\nAS $function$\nBEGIN\n  PERFORM public.create_schema_backup(\'auto\', NULL);\nEND;\n$function$\n;\n\nCREATE OR REPLACE FUNCTION public.export_schema_sql()\n RETURNS text\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO \'public\', \'pg_catalog\'\nAS $function$\nDECLARE\n  out_sql text := \'\';\n  r record;\n  cols text;\n  pk text;\n  policy_cmd text;\nBEGIN\n  -- Apenas admins\n  IF NOT public.has_role(auth.uid(), \'admin\') THEN\n    RAISE EXCEPTION \'forbidden\';\n  END IF;\n\n  out_sql := \'-- Schema dump (public) gerado em \' || now()::text || E\'\\n\';\n  out_sql := out_sql || E\'-- Apenas DDL. Não inclui dados.\\n\\n\';\n\n  -- 1) ENUMS\n  out_sql := out_sql || E\'-- =====================\\n-- ENUMS\\n-- =====================\\n\';\n  FOR r IN\n    SELECT n.nspname, t.typname,\n           string_agg(quote_literal(e.enumlabel), \', \' ORDER BY e.enumsortorder) AS labels\n    FROM pg_type t\n    JOIN pg_enum e ON e.enumtypid = t.oid\n    JOIN pg_namespace n ON n.oid = t.typnamespace\n    WHERE n.nspname = \'public\'\n    GROUP BY n.nspname, t.typname\n    ORDER BY t.typname\n  LOOP\n    out_sql := out_sql || format(E\'CREATE TYPE %I.%I AS ENUM (%s);\\n\', r.nspname, r.typname, r.labels);\n  END LOOP;\n  out_sql := out_sql || E\'\\n\';\n\n  -- 2) TABELAS + COLUNAS + PK\n  out_sql := out_sql || E\'-- =====================\\n-- TABELAS\\n-- =====================\\n\';\n  FOR r IN\n    SELECT c.oid, c.relname\n    FROM pg_class c\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname = \'public\' AND c.relkind = \'r\'\n    ORDER BY c.relname\n  LOOP\n    -- colunas\n    SELECT string_agg(\n      format(\'  %I %s%s%s\',\n        a.attname,\n        format_type(a.atttypid, a.atttypmod),\n        CASE WHEN a.attnotnull THEN \' NOT NULL\' ELSE \'\' END,\n        CASE WHEN ad.adbin IS NOT NULL\n             THEN \' DEFAULT \' || pg_get_expr(ad.adbin, ad.adrelid)\n             ELSE \'\' END\n      ), E\',\\n\' ORDER BY a.attnum\n    )\n    INTO cols\n    FROM pg_attribute a\n    LEFT JOIN pg_attrdef ad ON ad.adrelid = a.attrelid AND ad.adnum = a.attnum\n    WHERE a.attrelid = r.oid AND a.attnum > 0 AND NOT a.attisdropped;\n\n    -- PK\n    SELECT format(\',\\n  CONSTRAINT %I PRIMARY KEY (%s)\',\n      con.conname,\n      (SELECT string_agg(quote_ident(att.attname), \', \' ORDER BY array_position(con.conkey, att.attnum))\n         FROM pg_attribute att\n        WHERE att.attrelid = r.oid AND att.attnum = ANY(con.conkey)))\n    INTO pk\n    FROM pg_constraint con\n    WHERE con.conrelid = r.oid AND con.contype = \'p\'\n    LIMIT 1;\n\n    out_sql := out_sql || format(E\'\\nCREATE TABLE public.%I (\\n%s%s\\n);\\n\',\n      r.relname, cols, COALESCE(pk, \'\'));\n  END LOOP;\n\n  -- 3) FK / UNIQUE / CHECK constraints (separados, depois de todas as tabelas)\n  out_sql := out_sql || E\'\\n-- =====================\\n-- CONSTRAINTS (FK/UNIQUE/CHECK)\\n-- =====================\\n\';\n  FOR r IN\n    SELECT c.relname AS table_name, con.conname,\n           pg_get_constraintdef(con.oid) AS def\n    FROM pg_constraint con\n    JOIN pg_class c ON c.oid = con.conrelid\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname = \'public\' AND con.contype IN (\'f\',\'u\',\'c\')\n    ORDER BY c.relname, con.conname\n  LOOP\n    out_sql := out_sql || format(E\'ALTER TABLE public.%I ADD CONSTRAINT %I %s;\\n\',\n      r.table_name, r.conname, r.def);\n  END LOOP;\n\n  -- 4) ÍNDICES (não-PK / não-unique-constraint)\n  out_sql := out_sql || E\'\\n-- =====================\\n-- ÍNDICES\\n-- =====================\\n\';\n  FOR r IN\n    SELECT indexdef\n    FROM pg_indexes\n    WHERE schemaname = \'public\'\n      AND indexname NOT IN (\n        SELECT conname FROM pg_constraint WHERE contype IN (\'p\',\'u\')\n      )\n    ORDER BY tablename, indexname\n  LOOP\n    out_sql := out_sql || r.indexdef || E\';\\n\';\n  END LOOP;\n\n  -- 5) RLS + POLICIES\n  out_sql := out_sql || E\'\\n-- =====================\\n-- ROW LEVEL SECURITY\\n-- =====================\\n\';\n  FOR r IN\n    SELECT c.relname\n    FROM pg_class c\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname=\'public\' AND c.relkind=\'r\' AND c.relrowsecurity\n    ORDER BY c.relname\n  LOOP\n    out_sql := out_sql || format(E\'ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY;\\n\', r.relname);\n  END LOOP;\n\n  out_sql := out_sql || E\'\\n-- Policies\\n\';\n  FOR r IN\n    SELECT schemaname, tablename, policyname, permissive, roles, cmd, qual, with_check\n    FROM pg_policies\n    WHERE schemaname=\'public\'\n    ORDER BY tablename, policyname\n  LOOP\n    policy_cmd := format(\'CREATE POLICY %I ON public.%I AS %s FOR %s TO %s\',\n      r.policyname, r.tablename,\n      COALESCE(r.permissive,\'PERMISSIVE\'),\n      r.cmd,\n      array_to_string(r.roles, \', \'));\n    IF r.qual IS NOT NULL THEN\n      policy_cmd := policy_cmd || \' USING (\' || r.qual || \')\';\n    END IF;\n    IF r.with_check IS NOT NULL THEN\n      policy_cmd := policy_cmd || \' WITH CHECK (\' || r.with_check || \')\';\n    END IF;\n    out_sql := out_sql || policy_cmd || E\';\\n\';\n  END LOOP;\n\n  -- 6) FUNÇÕES\n  out_sql := out_sql || E\'\\n-- =====================\\n-- FUNÇÕES\\n-- =====================\\n\';\n  FOR r IN\n    SELECT pg_get_functiondef(p.oid) AS def\n    FROM pg_proc p\n    JOIN pg_namespace n ON n.oid = p.pronamespace\n    WHERE n.nspname=\'public\' AND p.prokind = \'f\'\n    ORDER BY p.proname\n  LOOP\n    out_sql := out_sql || r.def || E\';\\n\\n\';\n  END LOOP;\n\n  -- 7) TRIGGERS\n  out_sql := out_sql || E\'-- =====================\\n-- TRIGGERS\\n-- =====================\\n\';\n  FOR r IN\n    SELECT pg_get_triggerdef(t.oid) AS def\n    FROM pg_trigger t\n    JOIN pg_class c ON c.oid = t.tgrelid\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname=\'public\' AND NOT t.tgisinternal\n    ORDER BY c.relname, t.tgname\n  LOOP\n    out_sql := out_sql || r.def || E\';\\n\';\n  END LOOP;\n\n  RETURN out_sql;\nEND;\n$function$\n;\n\nCREATE OR REPLACE FUNCTION public.export_schema_sql_internal()\n RETURNS text\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO \'public\', \'pg_catalog\'\nAS $function$\nDECLARE\n  out_sql text := \'\';\n  r record;\n  cols text;\n  pk text;\n  policy_cmd text;\nBEGIN\n  out_sql := \'-- Schema dump (public) gerado em \' || now()::text || E\'\\n\';\n  out_sql := out_sql || E\'-- Apenas DDL. Não inclui dados.\\n\\n\';\n\n  out_sql := out_sql || E\'-- =====================\\n-- ENUMS\\n-- =====================\\n\';\n  FOR r IN\n    SELECT n.nspname, t.typname,\n           string_agg(quote_literal(e.enumlabel), \', \' ORDER BY e.enumsortorder) AS labels\n    FROM pg_type t\n    JOIN pg_enum e ON e.enumtypid = t.oid\n    JOIN pg_namespace n ON n.oid = t.typnamespace\n    WHERE n.nspname = \'public\'\n    GROUP BY n.nspname, t.typname\n    ORDER BY t.typname\n  LOOP\n    out_sql := out_sql || format(E\'CREATE TYPE %I.%I AS ENUM (%s);\\n\', r.nspname, r.typname, r.labels);\n  END LOOP;\n  out_sql := out_sql || E\'\\n\';\n\n  out_sql := out_sql || E\'-- =====================\\n-- TABELAS\\n-- =====================\\n\';\n  FOR r IN\n    SELECT c.oid, c.relname\n    FROM pg_class c\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname = \'public\' AND c.relkind = \'r\'\n    ORDER BY c.relname\n  LOOP\n    SELECT string_agg(\n      format(\'  %I %s%s%s\',\n        a.attname,\n        format_type(a.atttypid, a.atttypmod),\n        CASE WHEN a.attnotnull THEN \' NOT NULL\' ELSE \'\' END,\n        CASE WHEN ad.adbin IS NOT NULL\n             THEN \' DEFAULT \' || pg_get_expr(ad.adbin, ad.adrelid)\n             ELSE \'\' END\n      ), E\',\\n\' ORDER BY a.attnum\n    )\n    INTO cols\n    FROM pg_attribute a\n    LEFT JOIN pg_attrdef ad ON ad.adrelid = a.attrelid AND ad.adnum = a.attnum\n    WHERE a.attrelid = r.oid AND a.attnum > 0 AND NOT a.attisdropped;\n\n    SELECT format(\',\\n  CONSTRAINT %I PRIMARY KEY (%s)\',\n      con.conname,\n      (SELECT string_agg(quote_ident(att.attname), \', \' ORDER BY array_position(con.conkey, att.attnum))\n         FROM pg_attribute att\n        WHERE att.attrelid = r.oid AND att.attnum = ANY(con.conkey)))\n    INTO pk\n    FROM pg_constraint con\n    WHERE con.conrelid = r.oid AND con.contype = \'p\'\n    LIMIT 1;\n\n    out_sql := out_sql || format(E\'\\nCREATE TABLE public.%I (\\n%s%s\\n);\\n\',\n      r.relname, cols, COALESCE(pk, \'\'));\n  END LOOP;\n\n  out_sql := out_sql || E\'\\n-- =====================\\n-- CONSTRAINTS (FK/UNIQUE/CHECK)\\n-- =====================\\n\';\n  FOR r IN\n    SELECT c.relname AS table_name, con.conname,\n           pg_get_constraintdef(con.oid) AS def\n    FROM pg_constraint con\n    JOIN pg_class c ON c.oid = con.conrelid\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname = \'public\' AND con.contype IN (\'f\',\'u\',\'c\')\n    ORDER BY c.relname, con.conname\n  LOOP\n    out_sql := out_sql || format(E\'ALTER TABLE public.%I ADD CONSTRAINT %I %s;\\n\',\n      r.table_name, r.conname, r.def);\n  END LOOP;\n\n  out_sql := out_sql || E\'\\n-- =====================\\n-- ÍNDICES\\n-- =====================\\n\';\n  FOR r IN\n    SELECT indexdef\n    FROM pg_indexes\n    WHERE schemaname = \'public\'\n      AND indexname NOT IN (SELECT conname FROM pg_constraint WHERE contype IN (\'p\',\'u\'))\n    ORDER BY tablename, indexname\n  LOOP\n    out_sql := out_sql || r.indexdef || E\';\\n\';\n  END LOOP;\n\n  out_sql := out_sql || E\'\\n-- =====================\\n-- ROW LEVEL SECURITY\\n-- =====================\\n\';\n  FOR r IN\n    SELECT c.relname FROM pg_class c\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname=\'public\' AND c.relkind=\'r\' AND c.relrowsecurity\n    ORDER BY c.relname\n  LOOP\n    out_sql := out_sql || format(E\'ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY;\\n\', r.relname);\n  END LOOP;\n\n  out_sql := out_sql || E\'\\n-- Policies\\n\';\n  FOR r IN\n    SELECT schemaname, tablename, policyname, permissive, roles, cmd, qual, with_check\n    FROM pg_policies WHERE schemaname=\'public\' ORDER BY tablename, policyname\n  LOOP\n    policy_cmd := format(\'CREATE POLICY %I ON public.%I AS %s FOR %s TO %s\',\n      r.policyname, r.tablename, COALESCE(r.permissive,\'PERMISSIVE\'),\n      r.cmd, array_to_string(r.roles, \', \'));\n    IF r.qual IS NOT NULL THEN policy_cmd := policy_cmd || \' USING (\' || r.qual || \')\'; END IF;\n    IF r.with_check IS NOT NULL THEN policy_cmd := policy_cmd || \' WITH CHECK (\' || r.with_check || \')\'; END IF;\n    out_sql := out_sql || policy_cmd || E\';\\n\';\n  END LOOP;\n\n  out_sql := out_sql || E\'\\n-- =====================\\n-- FUNÇÕES\\n-- =====================\\n\';\n  FOR r IN\n    SELECT pg_get_functiondef(p.oid) AS def\n    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n    WHERE n.nspname=\'public\' AND p.prokind=\'f\' ORDER BY p.proname\n  LOOP\n    out_sql := out_sql || r.def || E\';\\n\\n\';\n  END LOOP;\n\n  out_sql := out_sql || E\'-- =====================\\n-- TRIGGERS\\n-- =====================\\n\';\n  FOR r IN\n    SELECT pg_get_triggerdef(t.oid) AS def\n    FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname=\'public\' AND NOT t.tgisinternal\n    ORDER BY c.relname, t.tgname\n  LOOP\n    out_sql := out_sql || r.def || E\';\\n\';\n  END LOOP;\n\n  RETURN out_sql;\nEND;\n$function$\n;\n\nCREATE OR REPLACE FUNCTION public.handle_new_user()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO \'public\'\nAS $function$\nbegin\n  insert into public.profiles (id, email, display_name)\n  values (new.id, new.email, coalesce(new.raw_user_meta_data->>\'display_name\', split_part(new.email,\'@\',1)));\n  return new;\nend;\n$function$\n;\n\nCREATE OR REPLACE FUNCTION public.has_role(_user_id uuid, _role app_role)\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO \'public\'\nAS $function$\n  SELECT EXISTS (\n    SELECT 1 FROM public.user_roles\n    WHERE user_id = _user_id AND role = _role\n  )\n$function$\n;\n\nCREATE OR REPLACE FUNCTION public.set_updated_at()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO \'public\'\nAS $function$\nbegin new.updated_at = now(); return new; end;\n$function$\n;\n\n-- =====================\n-- TRIGGERS\n-- =====================\nCREATE TRIGGER campaigns_updated BEFORE UPDATE ON public.campaigns FOR EACH ROW EXECUTE FUNCTION set_updated_at();\nCREATE TRIGGER contacts_updated BEFORE UPDATE ON public.contacts FOR EACH ROW EXECUTE FUNCTION set_updated_at();\nCREATE TRIGGER profiles_updated BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION set_updated_at();\n', 30910, '2026-06-16 03:00:00');
INSERT INTO `schema_backups` (`id`, `created_by`, `source`, `sql`, `size_bytes`, `created_at`) VALUES
('3636a994-6b09-4cf3-bd20-6244bb3b3784', NULL, 'auto', '-- Schema dump (public) gerado em 2026-06-12 03:00:00.021148+00\n-- Apenas DDL. Não inclui dados.\n\n-- =====================\n-- ENUMS\n-- =====================\nCREATE TYPE public.app_role AS ENUM (\'admin\', \'user\');\nCREATE TYPE public.campaign_status AS ENUM (\'draft\', \'queued\', \'running\', \'done\', \'failed\', \'cancelled\');\nCREATE TYPE public.message_status AS ENUM (\'pending\', \'sending\', \'sent\', \'delivered\', \'read\', \'failed\');\nCREATE TYPE public.message_type AS ENUM (\'template\', \'text\', \'media\', \'interactive\');\nCREATE TYPE public.template_status AS ENUM (\'APPROVED\', \'PENDING\', \'REJECTED\', \'PAUSED\', \'DISABLED\');\n\n-- =====================\n-- TABELAS\n-- =====================\n\nCREATE TABLE public.audit_logs (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid,\n  actor_email text,\n  action text NOT NULL,\n  entity_type text,\n  entity_id text,\n  metadata jsonb NOT NULL DEFAULT \'{}\'::jsonb,\n  ip text,\n  user_agent text,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT audit_logs_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.campaign_messages (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL,\n  campaign_id uuid NOT NULL,\n  contact_id uuid,\n  to_phone text NOT NULL,\n  status message_status NOT NULL DEFAULT \'pending\'::message_status,\n  wa_message_id text,\n  error jsonb,\n  attempts integer NOT NULL DEFAULT 0,\n  sent_at timestamp with time zone,\n  delivered_at timestamp with time zone,\n  read_at timestamp with time zone,\n  failed_at timestamp with time zone,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\n  pricing_billable boolean,\n  pricing_category text,\n  pricing_model text,\n  conversation_id text,\n  conversation_origin text,\\n  CONSTRAINT campaign_messages_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.campaigns (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL,\n  name text NOT NULL,\n  message_type message_type NOT NULL,\n  template_id uuid,\n  list_id uuid,\n  payload jsonb NOT NULL DEFAULT \'{}\'::jsonb,\n  status campaign_status NOT NULL DEFAULT \'draft\'::campaign_status,\n  scheduled_at timestamp with time zone,\n  started_at timestamp with time zone,\n  finished_at timestamp with time zone,\n  totals jsonb NOT NULL DEFAULT \'{\"read\": 0, \"sent\": 0, \"total\": 0, \"failed\": 0, \"pending\": 0, \"delivered\": 0}\'::jsonb,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\n  updated_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT campaigns_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.contact_tags (\n  contact_id uuid NOT NULL,\n  tag_id uuid NOT NULL,\n  user_id uuid NOT NULL,\\n  CONSTRAINT contact_tags_pkey PRIMARY KEY (contact_id, tag_id)\n);\n\nCREATE TABLE public.contacts (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL,\n  phone_e164 text NOT NULL,\n  name text,\n  email text,\n  custom_fields jsonb NOT NULL DEFAULT \'{}\'::jsonb,\n  opted_out boolean NOT NULL DEFAULT false,\n  source text,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\n  updated_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT contacts_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.list_contacts (\n  list_id uuid NOT NULL,\n  contact_id uuid NOT NULL,\n  user_id uuid NOT NULL,\n  added_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT list_contacts_pkey PRIMARY KEY (list_id, contact_id)\n);\n\nCREATE TABLE public.lists (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL,\n  name text NOT NULL,\n  description text,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT lists_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.platform_settings (\n  id smallint NOT NULL DEFAULT 1,\n  meta_app_id text,\n  meta_app_secret text,\n  meta_config_id text,\n  meta_graph_version text NOT NULL DEFAULT \'v20.0\'::text,\n  updated_at timestamp with time zone NOT NULL DEFAULT now(),\n  updated_by uuid,\n  head_tags text,\n  body_tags text,\n  cron_secret text,\\n  CONSTRAINT platform_settings_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.profiles (\n  id uuid NOT NULL,\n  display_name text,\n  email text,\n  whatsapp_phone_number_id text,\n  whatsapp_waba_id text,\n  whatsapp_business_phone text,\n  api_key text NOT NULL DEFAULT encode(extensions.gen_random_bytes(24), \'hex\'::text),\n  rate_limit_per_second integer NOT NULL DEFAULT 20,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\n  updated_at timestamp with time zone NOT NULL DEFAULT now(),\n  whatsapp_access_token text,\n  whatsapp_app_secret text,\n  whatsapp_verify_token text,\n  meta_graph_version text NOT NULL DEFAULT \'v20.0\'::text,\n  avatar_url text,\n  full_name text,\n  phone text,\n  company_name text,\n  company_document text,\n  company_website text,\n  company_address text,\\n  CONSTRAINT profiles_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.schema_backups (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\n  source text NOT NULL DEFAULT \'auto\'::text,\n  size_bytes integer NOT NULL DEFAULT 0,\n  sql text NOT NULL,\n  created_by uuid,\\n  CONSTRAINT schema_backups_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.tags (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL,\n  name text NOT NULL,\n  color text NOT NULL DEFAULT \'#25D366\'::text,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT tags_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.templates (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL,\n  meta_template_id text,\n  name text NOT NULL,\n  language text NOT NULL,\n  category text,\n  status template_status NOT NULL DEFAULT \'PENDING\'::template_status,\n  components jsonb NOT NULL DEFAULT \'[]\'::jsonb,\n  synced_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT templates_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.user_roles (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL,\n  role app_role NOT NULL,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT user_roles_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.webhook_events (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  source text NOT NULL DEFAULT \'whatsapp\'::text,\n  raw jsonb NOT NULL,\n  processed boolean NOT NULL DEFAULT false,\n  received_at timestamp with time zone NOT NULL DEFAULT now(),\n  user_id uuid,\\n  CONSTRAINT webhook_events_pkey PRIMARY KEY (id)\n);\n\n-- =====================\n-- CONSTRAINTS (FK/UNIQUE/CHECK)\n-- =====================\nALTER TABLE public.audit_logs ADD CONSTRAINT audit_logs_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE SET NULL;\nALTER TABLE public.campaign_messages ADD CONSTRAINT campaign_messages_campaign_id_fkey FOREIGN KEY (campaign_id) REFERENCES campaigns(id) ON DELETE CASCADE;\nALTER TABLE public.campaign_messages ADD CONSTRAINT campaign_messages_contact_id_fkey FOREIGN KEY (contact_id) REFERENCES contacts(id) ON DELETE SET NULL;\nALTER TABLE public.campaign_messages ADD CONSTRAINT campaign_messages_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.campaigns ADD CONSTRAINT campaigns_list_id_fkey FOREIGN KEY (list_id) REFERENCES lists(id) ON DELETE SET NULL;\nALTER TABLE public.campaigns ADD CONSTRAINT campaigns_template_id_fkey FOREIGN KEY (template_id) REFERENCES templates(id) ON DELETE SET NULL;\nALTER TABLE public.campaigns ADD CONSTRAINT campaigns_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.contact_tags ADD CONSTRAINT contact_tags_contact_id_fkey FOREIGN KEY (contact_id) REFERENCES contacts(id) ON DELETE CASCADE;\nALTER TABLE public.contact_tags ADD CONSTRAINT contact_tags_tag_id_fkey FOREIGN KEY (tag_id) REFERENCES tags(id) ON DELETE CASCADE;\nALTER TABLE public.contact_tags ADD CONSTRAINT contact_tags_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.contacts ADD CONSTRAINT contacts_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.contacts ADD CONSTRAINT contacts_user_id_phone_e164_key UNIQUE (user_id, phone_e164);\nALTER TABLE public.list_contacts ADD CONSTRAINT list_contacts_contact_id_fkey FOREIGN KEY (contact_id) REFERENCES contacts(id) ON DELETE CASCADE;\nALTER TABLE public.list_contacts ADD CONSTRAINT list_contacts_list_id_fkey FOREIGN KEY (list_id) REFERENCES lists(id) ON DELETE CASCADE;\nALTER TABLE public.list_contacts ADD CONSTRAINT list_contacts_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.lists ADD CONSTRAINT lists_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.platform_settings ADD CONSTRAINT platform_settings_id_check CHECK ((id = 1));\nALTER TABLE public.platform_settings ADD CONSTRAINT platform_settings_updated_by_fkey FOREIGN KEY (updated_by) REFERENCES auth.users(id) ON DELETE SET NULL;\nALTER TABLE public.profiles ADD CONSTRAINT profiles_api_key_key UNIQUE (api_key);\nALTER TABLE public.profiles ADD CONSTRAINT profiles_id_fkey FOREIGN KEY (id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.tags ADD CONSTRAINT tags_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.tags ADD CONSTRAINT tags_user_id_name_key UNIQUE (user_id, name);\nALTER TABLE public.templates ADD CONSTRAINT templates_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.templates ADD CONSTRAINT templates_user_id_name_language_key UNIQUE (user_id, name, language);\nALTER TABLE public.user_roles ADD CONSTRAINT user_roles_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.user_roles ADD CONSTRAINT user_roles_user_id_role_key UNIQUE (user_id, role);\n\n-- =====================\n-- ÍNDICES\n-- =====================\nCREATE INDEX audit_logs_action_idx ON public.audit_logs USING btree (action);\nCREATE INDEX audit_logs_created_idx ON public.audit_logs USING btree (created_at DESC);\nCREATE INDEX audit_logs_user_idx ON public.audit_logs USING btree (user_id, created_at DESC);\nCREATE INDEX cm_pending_idx ON public.campaign_messages USING btree (campaign_id, status);\nCREATE INDEX cm_user_idx ON public.campaign_messages USING btree (user_id, status);\nCREATE INDEX cm_wa_id_idx ON public.campaign_messages USING btree (wa_message_id);\nCREATE INDEX idx_campaign_messages_billing ON public.campaign_messages USING btree (user_id, created_at DESC, pricing_category);\nCREATE INDEX idx_campaign_messages_status_updated ON public.campaign_messages USING btree (status, sent_at);\nCREATE INDEX contacts_user_idx ON public.contacts USING btree (user_id);\nCREATE INDEX list_contacts_list_idx ON public.list_contacts USING btree (list_id);\nCREATE INDEX idx_schema_backups_created_at ON public.schema_backups USING btree (created_at DESC);\nCREATE INDEX idx_webhook_events_received_at ON public.webhook_events USING btree (received_at);\nCREATE INDEX webhook_events_user_id_received_at_idx ON public.webhook_events USING btree (user_id, received_at DESC);\n\n-- =====================\n-- ROW LEVEL SECURITY\n-- =====================\nALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.campaign_messages ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.campaigns ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.contact_tags ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.contacts ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.list_contacts ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.lists ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.platform_settings ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.schema_backups ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.tags ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.templates ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.webhook_events ENABLE ROW LEVEL SECURITY;\n\n-- Policies\nCREATE POLICY audit_logs_no_delete ON public.audit_logs AS RESTRICTIVE FOR DELETE TO anon, authenticated USING (false);\nCREATE POLICY audit_logs_no_update ON public.audit_logs AS RESTRICTIVE FOR UPDATE TO anon, authenticated USING (false);\nCREATE POLICY audit_logs_no_write ON public.audit_logs AS RESTRICTIVE FOR INSERT TO anon, authenticated WITH CHECK (false);\nCREATE POLICY audit_logs_select_own_or_admin ON public.audit_logs AS PERMISSIVE FOR SELECT TO authenticated USING (((auth.uid() = user_id) OR has_role(auth.uid(), \'admin\'::app_role)));\nCREATE POLICY cm_delete_own ON public.campaign_messages AS PERMISSIVE FOR DELETE TO authenticated USING ((auth.uid() = user_id));\nCREATE POLICY cm_insert_own ON public.campaign_messages AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY cm_select_own ON public.campaign_messages AS PERMISSIVE FOR SELECT TO authenticated USING ((auth.uid() = user_id));\nCREATE POLICY cm_update_own ON public.campaign_messages AS PERMISSIVE FOR UPDATE TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY campaigns_all_own ON public.campaigns AS PERMISSIVE FOR ALL TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY contact_tags_all_own ON public.contact_tags AS PERMISSIVE FOR ALL TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY contacts_all_own ON public.contacts AS PERMISSIVE FOR ALL TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY list_contacts_all_own ON public.list_contacts AS PERMISSIVE FOR ALL TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY lists_all_own ON public.lists AS PERMISSIVE FOR ALL TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY platform_settings_admin_select ON public.platform_settings AS PERMISSIVE FOR SELECT TO authenticated USING (has_role(auth.uid(), \'admin\'::app_role));\nCREATE POLICY platform_settings_admin_update ON public.platform_settings AS PERMISSIVE FOR UPDATE TO authenticated USING (has_role(auth.uid(), \'admin\'::app_role)) WITH CHECK (has_role(auth.uid(), \'admin\'::app_role));\nCREATE POLICY profiles_insert_own ON public.profiles AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK ((auth.uid() = id));\nCREATE POLICY profiles_select_own ON public.profiles AS PERMISSIVE FOR SELECT TO authenticated USING ((auth.uid() = id));\nCREATE POLICY profiles_update_own ON public.profiles AS PERMISSIVE FOR UPDATE TO authenticated USING ((auth.uid() = id)) WITH CHECK ((auth.uid() = id));\nCREATE POLICY schema_backups_admin_delete ON public.schema_backups AS PERMISSIVE FOR DELETE TO authenticated USING (has_role(auth.uid(), \'admin\'::app_role));\nCREATE POLICY schema_backups_admin_insert ON public.schema_backups AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (has_role(auth.uid(), \'admin\'::app_role));\nCREATE POLICY schema_backups_admin_select ON public.schema_backups AS PERMISSIVE FOR SELECT TO authenticated USING (has_role(auth.uid(), \'admin\'::app_role));\nCREATE POLICY tags_all_own ON public.tags AS PERMISSIVE FOR ALL TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY templates_all_own ON public.templates AS PERMISSIVE FOR ALL TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY user_roles_admin_manage ON public.user_roles AS PERMISSIVE FOR ALL TO authenticated USING (has_role(auth.uid(), \'admin\'::app_role)) WITH CHECK (has_role(auth.uid(), \'admin\'::app_role));\nCREATE POLICY user_roles_block_self_delete ON public.user_roles AS RESTRICTIVE FOR DELETE TO authenticated USING ((user_id <> auth.uid()));\nCREATE POLICY user_roles_block_self_insert ON public.user_roles AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK ((user_id <> auth.uid()));\nCREATE POLICY user_roles_block_self_update ON public.user_roles AS RESTRICTIVE FOR UPDATE TO authenticated USING ((user_id <> auth.uid())) WITH CHECK ((user_id <> auth.uid()));\nCREATE POLICY user_roles_select_own ON public.user_roles AS PERMISSIVE FOR SELECT TO authenticated USING (((auth.uid() = user_id) OR has_role(auth.uid(), \'admin\'::app_role)));\nCREATE POLICY webhook_events_no_delete ON public.webhook_events AS RESTRICTIVE FOR DELETE TO anon, authenticated USING (false);\nCREATE POLICY webhook_events_no_insert ON public.webhook_events AS RESTRICTIVE FOR INSERT TO anon, authenticated WITH CHECK (false);\nCREATE POLICY webhook_events_no_update ON public.webhook_events AS RESTRICTIVE FOR UPDATE TO anon, authenticated USING (false) WITH CHECK (false);\nCREATE POLICY webhook_events_select_own ON public.webhook_events AS PERMISSIVE FOR SELECT TO authenticated USING ((auth.uid() = user_id));\n\n-- =====================\n-- FUNÇÕES\n-- =====================\nCREATE OR REPLACE FUNCTION public.assign_default_role()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO \'public\'\nAS $function$\nDECLARE\n  has_any_admin boolean;\nBEGIN\n  SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE role = \'admin\') INTO has_any_admin;\n  IF NOT has_any_admin THEN\n    INSERT INTO public.user_roles (user_id, role) VALUES (NEW.id, \'admin\')\n      ON CONFLICT DO NOTHING;\n  ELSE\n    INSERT INTO public.user_roles (user_id, role) VALUES (NEW.id, \'user\')\n      ON CONFLICT DO NOTHING;\n  END IF;\n  RETURN NEW;\nEND;\n$function$\n;\n\nCREATE OR REPLACE FUNCTION public.create_schema_backup(_source text DEFAULT \'auto\'::text, _user uuid DEFAULT NULL::uuid)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO \'public\', \'pg_catalog\'\nAS $function$\nDECLARE\n  dump text;\n  new_id uuid;\nBEGIN\n  -- Gera o dump (a função export_schema_sql exige admin; aqui contornamos por se rodar via cron/service_role)\n  -- Por isso replicamos a chamada interna como SECURITY DEFINER e pulamos o has_role quando _user é NULL (cron).\n  IF _user IS NOT NULL AND NOT public.has_role(_user, \'admin\') THEN\n    RAISE EXCEPTION \'forbidden\';\n  END IF;\n\n  -- Chama a função existente como superuser deste DEFINER\n  EXECUTE \'SELECT public.export_schema_sql_internal()\' INTO dump;\n\n  INSERT INTO public.schema_backups (source, size_bytes, sql, created_by)\n  VALUES (COALESCE(_source, \'auto\'), COALESCE(length(dump), 0), COALESCE(dump, \'\'), _user)\n  RETURNING id INTO new_id;\n\n  -- Mantém apenas as 30 versões mais recentes\n  DELETE FROM public.schema_backups\n   WHERE id IN (\n     SELECT id FROM public.schema_backups\n      ORDER BY created_at DESC OFFSET 30\n   );\n\n  RETURN new_id;\nEND;\n$function$\n;\n\nCREATE OR REPLACE FUNCTION public.cron_create_schema_backup()\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO \'public\', \'pg_catalog\'\nAS $function$\nBEGIN\n  PERFORM public.create_schema_backup(\'auto\', NULL);\nEND;\n$function$\n;\n\nCREATE OR REPLACE FUNCTION public.export_schema_sql()\n RETURNS text\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO \'public\', \'pg_catalog\'\nAS $function$\nDECLARE\n  out_sql text := \'\';\n  r record;\n  cols text;\n  pk text;\n  policy_cmd text;\nBEGIN\n  -- Apenas admins\n  IF NOT public.has_role(auth.uid(), \'admin\') THEN\n    RAISE EXCEPTION \'forbidden\';\n  END IF;\n\n  out_sql := \'-- Schema dump (public) gerado em \' || now()::text || E\'\\n\';\n  out_sql := out_sql || E\'-- Apenas DDL. Não inclui dados.\\n\\n\';\n\n  -- 1) ENUMS\n  out_sql := out_sql || E\'-- =====================\\n-- ENUMS\\n-- =====================\\n\';\n  FOR r IN\n    SELECT n.nspname, t.typname,\n           string_agg(quote_literal(e.enumlabel), \', \' ORDER BY e.enumsortorder) AS labels\n    FROM pg_type t\n    JOIN pg_enum e ON e.enumtypid = t.oid\n    JOIN pg_namespace n ON n.oid = t.typnamespace\n    WHERE n.nspname = \'public\'\n    GROUP BY n.nspname, t.typname\n    ORDER BY t.typname\n  LOOP\n    out_sql := out_sql || format(E\'CREATE TYPE %I.%I AS ENUM (%s);\\n\', r.nspname, r.typname, r.labels);\n  END LOOP;\n  out_sql := out_sql || E\'\\n\';\n\n  -- 2) TABELAS + COLUNAS + PK\n  out_sql := out_sql || E\'-- =====================\\n-- TABELAS\\n-- =====================\\n\';\n  FOR r IN\n    SELECT c.oid, c.relname\n    FROM pg_class c\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname = \'public\' AND c.relkind = \'r\'\n    ORDER BY c.relname\n  LOOP\n    -- colunas\n    SELECT string_agg(\n      format(\'  %I %s%s%s\',\n        a.attname,\n        format_type(a.atttypid, a.atttypmod),\n        CASE WHEN a.attnotnull THEN \' NOT NULL\' ELSE \'\' END,\n        CASE WHEN ad.adbin IS NOT NULL\n             THEN \' DEFAULT \' || pg_get_expr(ad.adbin, ad.adrelid)\n             ELSE \'\' END\n      ), E\',\\n\' ORDER BY a.attnum\n    )\n    INTO cols\n    FROM pg_attribute a\n    LEFT JOIN pg_attrdef ad ON ad.adrelid = a.attrelid AND ad.adnum = a.attnum\n    WHERE a.attrelid = r.oid AND a.attnum > 0 AND NOT a.attisdropped;\n\n    -- PK\n    SELECT format(\',\\n  CONSTRAINT %I PRIMARY KEY (%s)\',\n      con.conname,\n      (SELECT string_agg(quote_ident(att.attname), \', \' ORDER BY array_position(con.conkey, att.attnum))\n         FROM pg_attribute att\n        WHERE att.attrelid = r.oid AND att.attnum = ANY(con.conkey)))\n    INTO pk\n    FROM pg_constraint con\n    WHERE con.conrelid = r.oid AND con.contype = \'p\'\n    LIMIT 1;\n\n    out_sql := out_sql || format(E\'\\nCREATE TABLE public.%I (\\n%s%s\\n);\\n\',\n      r.relname, cols, COALESCE(pk, \'\'));\n  END LOOP;\n\n  -- 3) FK / UNIQUE / CHECK constraints (separados, depois de todas as tabelas)\n  out_sql := out_sql || E\'\\n-- =====================\\n-- CONSTRAINTS (FK/UNIQUE/CHECK)\\n-- =====================\\n\';\n  FOR r IN\n    SELECT c.relname AS table_name, con.conname,\n           pg_get_constraintdef(con.oid) AS def\n    FROM pg_constraint con\n    JOIN pg_class c ON c.oid = con.conrelid\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname = \'public\' AND con.contype IN (\'f\',\'u\',\'c\')\n    ORDER BY c.relname, con.conname\n  LOOP\n    out_sql := out_sql || format(E\'ALTER TABLE public.%I ADD CONSTRAINT %I %s;\\n\',\n      r.table_name, r.conname, r.def);\n  END LOOP;\n\n  -- 4) ÍNDICES (não-PK / não-unique-constraint)\n  out_sql := out_sql || E\'\\n-- =====================\\n-- ÍNDICES\\n-- =====================\\n\';\n  FOR r IN\n    SELECT indexdef\n    FROM pg_indexes\n    WHERE schemaname = \'public\'\n      AND indexname NOT IN (\n        SELECT conname FROM pg_constraint WHERE contype IN (\'p\',\'u\')\n      )\n    ORDER BY tablename, indexname\n  LOOP\n    out_sql := out_sql || r.indexdef || E\';\\n\';\n  END LOOP;\n\n  -- 5) RLS + POLICIES\n  out_sql := out_sql || E\'\\n-- =====================\\n-- ROW LEVEL SECURITY\\n-- =====================\\n\';\n  FOR r IN\n    SELECT c.relname\n    FROM pg_class c\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname=\'public\' AND c.relkind=\'r\' AND c.relrowsecurity\n    ORDER BY c.relname\n  LOOP\n    out_sql := out_sql || format(E\'ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY;\\n\', r.relname);\n  END LOOP;\n\n  out_sql := out_sql || E\'\\n-- Policies\\n\';\n  FOR r IN\n    SELECT schemaname, tablename, policyname, permissive, roles, cmd, qual, with_check\n    FROM pg_policies\n    WHERE schemaname=\'public\'\n    ORDER BY tablename, policyname\n  LOOP\n    policy_cmd := format(\'CREATE POLICY %I ON public.%I AS %s FOR %s TO %s\',\n      r.policyname, r.tablename,\n      COALESCE(r.permissive,\'PERMISSIVE\'),\n      r.cmd,\n      array_to_string(r.roles, \', \'));\n    IF r.qual IS NOT NULL THEN\n      policy_cmd := policy_cmd || \' USING (\' || r.qual || \')\';\n    END IF;\n    IF r.with_check IS NOT NULL THEN\n      policy_cmd := policy_cmd || \' WITH CHECK (\' || r.with_check || \')\';\n    END IF;\n    out_sql := out_sql || policy_cmd || E\';\\n\';\n  END LOOP;\n\n  -- 6) FUNÇÕES\n  out_sql := out_sql || E\'\\n-- =====================\\n-- FUNÇÕES\\n-- =====================\\n\';\n  FOR r IN\n    SELECT pg_get_functiondef(p.oid) AS def\n    FROM pg_proc p\n    JOIN pg_namespace n ON n.oid = p.pronamespace\n    WHERE n.nspname=\'public\' AND p.prokind = \'f\'\n    ORDER BY p.proname\n  LOOP\n    out_sql := out_sql || r.def || E\';\\n\\n\';\n  END LOOP;\n\n  -- 7) TRIGGERS\n  out_sql := out_sql || E\'-- =====================\\n-- TRIGGERS\\n-- =====================\\n\';\n  FOR r IN\n    SELECT pg_get_triggerdef(t.oid) AS def\n    FROM pg_trigger t\n    JOIN pg_class c ON c.oid = t.tgrelid\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname=\'public\' AND NOT t.tgisinternal\n    ORDER BY c.relname, t.tgname\n  LOOP\n    out_sql := out_sql || r.def || E\';\\n\';\n  END LOOP;\n\n  RETURN out_sql;\nEND;\n$function$\n;\n\nCREATE OR REPLACE FUNCTION public.export_schema_sql_internal()\n RETURNS text\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO \'public\', \'pg_catalog\'\nAS $function$\nDECLARE\n  out_sql text := \'\';\n  r record;\n  cols text;\n  pk text;\n  policy_cmd text;\nBEGIN\n  out_sql := \'-- Schema dump (public) gerado em \' || now()::text || E\'\\n\';\n  out_sql := out_sql || E\'-- Apenas DDL. Não inclui dados.\\n\\n\';\n\n  out_sql := out_sql || E\'-- =====================\\n-- ENUMS\\n-- =====================\\n\';\n  FOR r IN\n    SELECT n.nspname, t.typname,\n           string_agg(quote_literal(e.enumlabel), \', \' ORDER BY e.enumsortorder) AS labels\n    FROM pg_type t\n    JOIN pg_enum e ON e.enumtypid = t.oid\n    JOIN pg_namespace n ON n.oid = t.typnamespace\n    WHERE n.nspname = \'public\'\n    GROUP BY n.nspname, t.typname\n    ORDER BY t.typname\n  LOOP\n    out_sql := out_sql || format(E\'CREATE TYPE %I.%I AS ENUM (%s);\\n\', r.nspname, r.typname, r.labels);\n  END LOOP;\n  out_sql := out_sql || E\'\\n\';\n\n  out_sql := out_sql || E\'-- =====================\\n-- TABELAS\\n-- =====================\\n\';\n  FOR r IN\n    SELECT c.oid, c.relname\n    FROM pg_class c\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname = \'public\' AND c.relkind = \'r\'\n    ORDER BY c.relname\n  LOOP\n    SELECT string_agg(\n      format(\'  %I %s%s%s\',\n        a.attname,\n        format_type(a.atttypid, a.atttypmod),\n        CASE WHEN a.attnotnull THEN \' NOT NULL\' ELSE \'\' END,\n        CASE WHEN ad.adbin IS NOT NULL\n             THEN \' DEFAULT \' || pg_get_expr(ad.adbin, ad.adrelid)\n             ELSE \'\' END\n      ), E\',\\n\' ORDER BY a.attnum\n    )\n    INTO cols\n    FROM pg_attribute a\n    LEFT JOIN pg_attrdef ad ON ad.adrelid = a.attrelid AND ad.adnum = a.attnum\n    WHERE a.attrelid = r.oid AND a.attnum > 0 AND NOT a.attisdropped;\n\n    SELECT format(\',\\n  CONSTRAINT %I PRIMARY KEY (%s)\',\n      con.conname,\n      (SELECT string_agg(quote_ident(att.attname), \', \' ORDER BY array_position(con.conkey, att.attnum))\n         FROM pg_attribute att\n        WHERE att.attrelid = r.oid AND att.attnum = ANY(con.conkey)))\n    INTO pk\n    FROM pg_constraint con\n    WHERE con.conrelid = r.oid AND con.contype = \'p\'\n    LIMIT 1;\n\n    out_sql := out_sql || format(E\'\\nCREATE TABLE public.%I (\\n%s%s\\n);\\n\',\n      r.relname, cols, COALESCE(pk, \'\'));\n  END LOOP;\n\n  out_sql := out_sql || E\'\\n-- =====================\\n-- CONSTRAINTS (FK/UNIQUE/CHECK)\\n-- =====================\\n\';\n  FOR r IN\n    SELECT c.relname AS table_name, con.conname,\n           pg_get_constraintdef(con.oid) AS def\n    FROM pg_constraint con\n    JOIN pg_class c ON c.oid = con.conrelid\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname = \'public\' AND con.contype IN (\'f\',\'u\',\'c\')\n    ORDER BY c.relname, con.conname\n  LOOP\n    out_sql := out_sql || format(E\'ALTER TABLE public.%I ADD CONSTRAINT %I %s;\\n\',\n      r.table_name, r.conname, r.def);\n  END LOOP;\n\n  out_sql := out_sql || E\'\\n-- =====================\\n-- ÍNDICES\\n-- =====================\\n\';\n  FOR r IN\n    SELECT indexdef\n    FROM pg_indexes\n    WHERE schemaname = \'public\'\n      AND indexname NOT IN (SELECT conname FROM pg_constraint WHERE contype IN (\'p\',\'u\'))\n    ORDER BY tablename, indexname\n  LOOP\n    out_sql := out_sql || r.indexdef || E\';\\n\';\n  END LOOP;\n\n  out_sql := out_sql || E\'\\n-- =====================\\n-- ROW LEVEL SECURITY\\n-- =====================\\n\';\n  FOR r IN\n    SELECT c.relname FROM pg_class c\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname=\'public\' AND c.relkind=\'r\' AND c.relrowsecurity\n    ORDER BY c.relname\n  LOOP\n    out_sql := out_sql || format(E\'ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY;\\n\', r.relname);\n  END LOOP;\n\n  out_sql := out_sql || E\'\\n-- Policies\\n\';\n  FOR r IN\n    SELECT schemaname, tablename, policyname, permissive, roles, cmd, qual, with_check\n    FROM pg_policies WHERE schemaname=\'public\' ORDER BY tablename, policyname\n  LOOP\n    policy_cmd := format(\'CREATE POLICY %I ON public.%I AS %s FOR %s TO %s\',\n      r.policyname, r.tablename, COALESCE(r.permissive,\'PERMISSIVE\'),\n      r.cmd, array_to_string(r.roles, \', \'));\n    IF r.qual IS NOT NULL THEN policy_cmd := policy_cmd || \' USING (\' || r.qual || \')\'; END IF;\n    IF r.with_check IS NOT NULL THEN policy_cmd := policy_cmd || \' WITH CHECK (\' || r.with_check || \')\'; END IF;\n    out_sql := out_sql || policy_cmd || E\';\\n\';\n  END LOOP;\n\n  out_sql := out_sql || E\'\\n-- =====================\\n-- FUNÇÕES\\n-- =====================\\n\';\n  FOR r IN\n    SELECT pg_get_functiondef(p.oid) AS def\n    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n    WHERE n.nspname=\'public\' AND p.prokind=\'f\' ORDER BY p.proname\n  LOOP\n    out_sql := out_sql || r.def || E\';\\n\\n\';\n  END LOOP;\n\n  out_sql := out_sql || E\'-- =====================\\n-- TRIGGERS\\n-- =====================\\n\';\n  FOR r IN\n    SELECT pg_get_triggerdef(t.oid) AS def\n    FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname=\'public\' AND NOT t.tgisinternal\n    ORDER BY c.relname, t.tgname\n  LOOP\n    out_sql := out_sql || r.def || E\';\\n\';\n  END LOOP;\n\n  RETURN out_sql;\nEND;\n$function$\n;\n\nCREATE OR REPLACE FUNCTION public.handle_new_user()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO \'public\'\nAS $function$\nbegin\n  insert into public.profiles (id, email, display_name)\n  values (new.id, new.email, coalesce(new.raw_user_meta_data->>\'display_name\', split_part(new.email,\'@\',1)));\n  return new;\nend;\n$function$\n;\n\nCREATE OR REPLACE FUNCTION public.has_role(_user_id uuid, _role app_role)\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO \'public\'\nAS $function$\n  SELECT EXISTS (\n    SELECT 1 FROM public.user_roles\n    WHERE user_id = _user_id AND role = _role\n  )\n$function$\n;\n\nCREATE OR REPLACE FUNCTION public.set_updated_at()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO \'public\'\nAS $function$\nbegin new.updated_at = now(); return new; end;\n$function$\n;\n\n-- =====================\n-- TRIGGERS\n-- =====================\nCREATE TRIGGER campaigns_updated BEFORE UPDATE ON public.campaigns FOR EACH ROW EXECUTE FUNCTION set_updated_at();\nCREATE TRIGGER contacts_updated BEFORE UPDATE ON public.contacts FOR EACH ROW EXECUTE FUNCTION set_updated_at();\nCREATE TRIGGER profiles_updated BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION set_updated_at();\n', 30910, '2026-06-12 03:00:00');
INSERT INTO `schema_backups` (`id`, `created_by`, `source`, `sql`, `size_bytes`, `created_at`) VALUES
('483da277-967b-4cfe-abc2-553a2658453f', NULL, 'auto', '-- Schema dump (public) gerado em 2026-05-29 03:00:00.045788+00\n-- Apenas DDL. Não inclui dados.\n\n-- =====================\n-- ENUMS\n-- =====================\nCREATE TYPE public.app_role AS ENUM (\'admin\', \'user\');\nCREATE TYPE public.campaign_status AS ENUM (\'draft\', \'queued\', \'running\', \'done\', \'failed\', \'cancelled\');\nCREATE TYPE public.message_status AS ENUM (\'pending\', \'sending\', \'sent\', \'delivered\', \'read\', \'failed\');\nCREATE TYPE public.message_type AS ENUM (\'template\', \'text\', \'media\', \'interactive\');\nCREATE TYPE public.template_status AS ENUM (\'APPROVED\', \'PENDING\', \'REJECTED\', \'PAUSED\', \'DISABLED\');\n\n-- =====================\n-- TABELAS\n-- =====================\n\nCREATE TABLE public.audit_logs (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid,\n  actor_email text,\n  action text NOT NULL,\n  entity_type text,\n  entity_id text,\n  metadata jsonb NOT NULL DEFAULT \'{}\'::jsonb,\n  ip text,\n  user_agent text,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT audit_logs_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.campaign_messages (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL,\n  campaign_id uuid NOT NULL,\n  contact_id uuid,\n  to_phone text NOT NULL,\n  status message_status NOT NULL DEFAULT \'pending\'::message_status,\n  wa_message_id text,\n  error jsonb,\n  attempts integer NOT NULL DEFAULT 0,\n  sent_at timestamp with time zone,\n  delivered_at timestamp with time zone,\n  read_at timestamp with time zone,\n  failed_at timestamp with time zone,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\n  pricing_billable boolean,\n  pricing_category text,\n  pricing_model text,\n  conversation_id text,\n  conversation_origin text,\\n  CONSTRAINT campaign_messages_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.campaigns (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL,\n  name text NOT NULL,\n  message_type message_type NOT NULL,\n  template_id uuid,\n  list_id uuid,\n  payload jsonb NOT NULL DEFAULT \'{}\'::jsonb,\n  status campaign_status NOT NULL DEFAULT \'draft\'::campaign_status,\n  scheduled_at timestamp with time zone,\n  started_at timestamp with time zone,\n  finished_at timestamp with time zone,\n  totals jsonb NOT NULL DEFAULT \'{\"read\": 0, \"sent\": 0, \"total\": 0, \"failed\": 0, \"pending\": 0, \"delivered\": 0}\'::jsonb,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\n  updated_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT campaigns_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.contact_tags (\n  contact_id uuid NOT NULL,\n  tag_id uuid NOT NULL,\n  user_id uuid NOT NULL,\\n  CONSTRAINT contact_tags_pkey PRIMARY KEY (contact_id, tag_id)\n);\n\nCREATE TABLE public.contacts (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL,\n  phone_e164 text NOT NULL,\n  name text,\n  email text,\n  custom_fields jsonb NOT NULL DEFAULT \'{}\'::jsonb,\n  opted_out boolean NOT NULL DEFAULT false,\n  source text,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\n  updated_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT contacts_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.list_contacts (\n  list_id uuid NOT NULL,\n  contact_id uuid NOT NULL,\n  user_id uuid NOT NULL,\n  added_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT list_contacts_pkey PRIMARY KEY (list_id, contact_id)\n);\n\nCREATE TABLE public.lists (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL,\n  name text NOT NULL,\n  description text,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT lists_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.platform_settings (\n  id smallint NOT NULL DEFAULT 1,\n  meta_app_id text,\n  meta_app_secret text,\n  meta_config_id text,\n  meta_graph_version text NOT NULL DEFAULT \'v20.0\'::text,\n  updated_at timestamp with time zone NOT NULL DEFAULT now(),\n  updated_by uuid,\n  head_tags text,\n  body_tags text,\n  cron_secret text,\\n  CONSTRAINT platform_settings_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.profiles (\n  id uuid NOT NULL,\n  display_name text,\n  email text,\n  whatsapp_phone_number_id text,\n  whatsapp_waba_id text,\n  whatsapp_business_phone text,\n  api_key text NOT NULL DEFAULT encode(extensions.gen_random_bytes(24), \'hex\'::text),\n  rate_limit_per_second integer NOT NULL DEFAULT 20,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\n  updated_at timestamp with time zone NOT NULL DEFAULT now(),\n  whatsapp_access_token text,\n  whatsapp_app_secret text,\n  whatsapp_verify_token text,\n  meta_graph_version text NOT NULL DEFAULT \'v20.0\'::text,\n  avatar_url text,\n  full_name text,\n  phone text,\n  company_name text,\n  company_document text,\n  company_website text,\n  company_address text,\\n  CONSTRAINT profiles_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.schema_backups (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\n  source text NOT NULL DEFAULT \'auto\'::text,\n  size_bytes integer NOT NULL DEFAULT 0,\n  sql text NOT NULL,\n  created_by uuid,\\n  CONSTRAINT schema_backups_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.tags (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL,\n  name text NOT NULL,\n  color text NOT NULL DEFAULT \'#25D366\'::text,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT tags_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.templates (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL,\n  meta_template_id text,\n  name text NOT NULL,\n  language text NOT NULL,\n  category text,\n  status template_status NOT NULL DEFAULT \'PENDING\'::template_status,\n  components jsonb NOT NULL DEFAULT \'[]\'::jsonb,\n  synced_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT templates_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.user_roles (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL,\n  role app_role NOT NULL,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT user_roles_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.webhook_events (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  source text NOT NULL DEFAULT \'whatsapp\'::text,\n  raw jsonb NOT NULL,\n  processed boolean NOT NULL DEFAULT false,\n  received_at timestamp with time zone NOT NULL DEFAULT now(),\n  user_id uuid,\\n  CONSTRAINT webhook_events_pkey PRIMARY KEY (id)\n);\n\n-- =====================\n-- CONSTRAINTS (FK/UNIQUE/CHECK)\n-- =====================\nALTER TABLE public.audit_logs ADD CONSTRAINT audit_logs_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE SET NULL;\nALTER TABLE public.campaign_messages ADD CONSTRAINT campaign_messages_campaign_id_fkey FOREIGN KEY (campaign_id) REFERENCES campaigns(id) ON DELETE CASCADE;\nALTER TABLE public.campaign_messages ADD CONSTRAINT campaign_messages_contact_id_fkey FOREIGN KEY (contact_id) REFERENCES contacts(id) ON DELETE SET NULL;\nALTER TABLE public.campaign_messages ADD CONSTRAINT campaign_messages_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.campaigns ADD CONSTRAINT campaigns_list_id_fkey FOREIGN KEY (list_id) REFERENCES lists(id) ON DELETE SET NULL;\nALTER TABLE public.campaigns ADD CONSTRAINT campaigns_template_id_fkey FOREIGN KEY (template_id) REFERENCES templates(id) ON DELETE SET NULL;\nALTER TABLE public.campaigns ADD CONSTRAINT campaigns_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.contact_tags ADD CONSTRAINT contact_tags_contact_id_fkey FOREIGN KEY (contact_id) REFERENCES contacts(id) ON DELETE CASCADE;\nALTER TABLE public.contact_tags ADD CONSTRAINT contact_tags_tag_id_fkey FOREIGN KEY (tag_id) REFERENCES tags(id) ON DELETE CASCADE;\nALTER TABLE public.contact_tags ADD CONSTRAINT contact_tags_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.contacts ADD CONSTRAINT contacts_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.contacts ADD CONSTRAINT contacts_user_id_phone_e164_key UNIQUE (user_id, phone_e164);\nALTER TABLE public.list_contacts ADD CONSTRAINT list_contacts_contact_id_fkey FOREIGN KEY (contact_id) REFERENCES contacts(id) ON DELETE CASCADE;\nALTER TABLE public.list_contacts ADD CONSTRAINT list_contacts_list_id_fkey FOREIGN KEY (list_id) REFERENCES lists(id) ON DELETE CASCADE;\nALTER TABLE public.list_contacts ADD CONSTRAINT list_contacts_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.lists ADD CONSTRAINT lists_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.platform_settings ADD CONSTRAINT platform_settings_id_check CHECK ((id = 1));\nALTER TABLE public.platform_settings ADD CONSTRAINT platform_settings_updated_by_fkey FOREIGN KEY (updated_by) REFERENCES auth.users(id) ON DELETE SET NULL;\nALTER TABLE public.profiles ADD CONSTRAINT profiles_api_key_key UNIQUE (api_key);\nALTER TABLE public.profiles ADD CONSTRAINT profiles_id_fkey FOREIGN KEY (id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.tags ADD CONSTRAINT tags_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.tags ADD CONSTRAINT tags_user_id_name_key UNIQUE (user_id, name);\nALTER TABLE public.templates ADD CONSTRAINT templates_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.templates ADD CONSTRAINT templates_user_id_name_language_key UNIQUE (user_id, name, language);\nALTER TABLE public.user_roles ADD CONSTRAINT user_roles_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.user_roles ADD CONSTRAINT user_roles_user_id_role_key UNIQUE (user_id, role);\n\n-- =====================\n-- ÍNDICES\n-- =====================\nCREATE INDEX audit_logs_action_idx ON public.audit_logs USING btree (action);\nCREATE INDEX audit_logs_created_idx ON public.audit_logs USING btree (created_at DESC);\nCREATE INDEX audit_logs_user_idx ON public.audit_logs USING btree (user_id, created_at DESC);\nCREATE INDEX cm_pending_idx ON public.campaign_messages USING btree (campaign_id, status);\nCREATE INDEX cm_user_idx ON public.campaign_messages USING btree (user_id, status);\nCREATE INDEX cm_wa_id_idx ON public.campaign_messages USING btree (wa_message_id);\nCREATE INDEX idx_campaign_messages_billing ON public.campaign_messages USING btree (user_id, created_at DESC, pricing_category);\nCREATE INDEX idx_campaign_messages_status_updated ON public.campaign_messages USING btree (status, sent_at);\nCREATE INDEX contacts_user_idx ON public.contacts USING btree (user_id);\nCREATE INDEX list_contacts_list_idx ON public.list_contacts USING btree (list_id);\nCREATE INDEX idx_schema_backups_created_at ON public.schema_backups USING btree (created_at DESC);\nCREATE INDEX idx_webhook_events_received_at ON public.webhook_events USING btree (received_at);\nCREATE INDEX webhook_events_user_id_received_at_idx ON public.webhook_events USING btree (user_id, received_at DESC);\n\n-- =====================\n-- ROW LEVEL SECURITY\n-- =====================\nALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.campaign_messages ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.campaigns ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.contact_tags ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.contacts ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.list_contacts ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.lists ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.platform_settings ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.schema_backups ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.tags ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.templates ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.webhook_events ENABLE ROW LEVEL SECURITY;\n\n-- Policies\nCREATE POLICY audit_logs_no_delete ON public.audit_logs AS RESTRICTIVE FOR DELETE TO anon, authenticated USING (false);\nCREATE POLICY audit_logs_no_update ON public.audit_logs AS RESTRICTIVE FOR UPDATE TO anon, authenticated USING (false);\nCREATE POLICY audit_logs_no_write ON public.audit_logs AS RESTRICTIVE FOR INSERT TO anon, authenticated WITH CHECK (false);\nCREATE POLICY audit_logs_select_own_or_admin ON public.audit_logs AS PERMISSIVE FOR SELECT TO authenticated USING (((auth.uid() = user_id) OR has_role(auth.uid(), \'admin\'::app_role)));\nCREATE POLICY cm_delete_own ON public.campaign_messages AS PERMISSIVE FOR DELETE TO authenticated USING ((auth.uid() = user_id));\nCREATE POLICY cm_insert_own ON public.campaign_messages AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY cm_select_own ON public.campaign_messages AS PERMISSIVE FOR SELECT TO authenticated USING ((auth.uid() = user_id));\nCREATE POLICY cm_update_own ON public.campaign_messages AS PERMISSIVE FOR UPDATE TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY campaigns_all_own ON public.campaigns AS PERMISSIVE FOR ALL TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY contact_tags_all_own ON public.contact_tags AS PERMISSIVE FOR ALL TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY contacts_all_own ON public.contacts AS PERMISSIVE FOR ALL TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY list_contacts_all_own ON public.list_contacts AS PERMISSIVE FOR ALL TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY lists_all_own ON public.lists AS PERMISSIVE FOR ALL TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY platform_settings_admin_select ON public.platform_settings AS PERMISSIVE FOR SELECT TO authenticated USING (has_role(auth.uid(), \'admin\'::app_role));\nCREATE POLICY platform_settings_admin_update ON public.platform_settings AS PERMISSIVE FOR UPDATE TO authenticated USING (has_role(auth.uid(), \'admin\'::app_role)) WITH CHECK (has_role(auth.uid(), \'admin\'::app_role));\nCREATE POLICY profiles_insert_own ON public.profiles AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK ((auth.uid() = id));\nCREATE POLICY profiles_select_own ON public.profiles AS PERMISSIVE FOR SELECT TO authenticated USING ((auth.uid() = id));\nCREATE POLICY profiles_update_own ON public.profiles AS PERMISSIVE FOR UPDATE TO authenticated USING ((auth.uid() = id)) WITH CHECK ((auth.uid() = id));\nCREATE POLICY schema_backups_admin_delete ON public.schema_backups AS PERMISSIVE FOR DELETE TO authenticated USING (has_role(auth.uid(), \'admin\'::app_role));\nCREATE POLICY schema_backups_admin_insert ON public.schema_backups AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (has_role(auth.uid(), \'admin\'::app_role));\nCREATE POLICY schema_backups_admin_select ON public.schema_backups AS PERMISSIVE FOR SELECT TO authenticated USING (has_role(auth.uid(), \'admin\'::app_role));\nCREATE POLICY tags_all_own ON public.tags AS PERMISSIVE FOR ALL TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY templates_all_own ON public.templates AS PERMISSIVE FOR ALL TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY user_roles_admin_manage ON public.user_roles AS PERMISSIVE FOR ALL TO authenticated USING (has_role(auth.uid(), \'admin\'::app_role)) WITH CHECK (has_role(auth.uid(), \'admin\'::app_role));\nCREATE POLICY user_roles_block_self_delete ON public.user_roles AS RESTRICTIVE FOR DELETE TO authenticated USING ((user_id <> auth.uid()));\nCREATE POLICY user_roles_block_self_insert ON public.user_roles AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK ((user_id <> auth.uid()));\nCREATE POLICY user_roles_block_self_update ON public.user_roles AS RESTRICTIVE FOR UPDATE TO authenticated USING ((user_id <> auth.uid())) WITH CHECK ((user_id <> auth.uid()));\nCREATE POLICY user_roles_select_own ON public.user_roles AS PERMISSIVE FOR SELECT TO authenticated USING (((auth.uid() = user_id) OR has_role(auth.uid(), \'admin\'::app_role)));\nCREATE POLICY webhook_events_no_access ON public.webhook_events AS PERMISSIVE FOR ALL TO anon, authenticated USING (false) WITH CHECK (false);\nCREATE POLICY webhook_events_select_own ON public.webhook_events AS PERMISSIVE FOR SELECT TO authenticated USING ((auth.uid() = user_id));\n\n-- =====================\n-- FUNÇÕES\n-- =====================\nCREATE OR REPLACE FUNCTION public.assign_default_role()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO \'public\'\nAS $function$\nDECLARE\n  has_any_admin boolean;\nBEGIN\n  SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE role = \'admin\') INTO has_any_admin;\n  IF NOT has_any_admin THEN\n    INSERT INTO public.user_roles (user_id, role) VALUES (NEW.id, \'admin\')\n      ON CONFLICT DO NOTHING;\n  ELSE\n    INSERT INTO public.user_roles (user_id, role) VALUES (NEW.id, \'user\')\n      ON CONFLICT DO NOTHING;\n  END IF;\n  RETURN NEW;\nEND;\n$function$\n;\n\nCREATE OR REPLACE FUNCTION public.create_schema_backup(_source text DEFAULT \'auto\'::text, _user uuid DEFAULT NULL::uuid)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO \'public\', \'pg_catalog\'\nAS $function$\nDECLARE\n  dump text;\n  new_id uuid;\nBEGIN\n  -- Gera o dump (a função export_schema_sql exige admin; aqui contornamos por se rodar via cron/service_role)\n  -- Por isso replicamos a chamada interna como SECURITY DEFINER e pulamos o has_role quando _user é NULL (cron).\n  IF _user IS NOT NULL AND NOT public.has_role(_user, \'admin\') THEN\n    RAISE EXCEPTION \'forbidden\';\n  END IF;\n\n  -- Chama a função existente como superuser deste DEFINER\n  EXECUTE \'SELECT public.export_schema_sql_internal()\' INTO dump;\n\n  INSERT INTO public.schema_backups (source, size_bytes, sql, created_by)\n  VALUES (COALESCE(_source, \'auto\'), COALESCE(length(dump), 0), COALESCE(dump, \'\'), _user)\n  RETURNING id INTO new_id;\n\n  -- Mantém apenas as 30 versões mais recentes\n  DELETE FROM public.schema_backups\n   WHERE id IN (\n     SELECT id FROM public.schema_backups\n      ORDER BY created_at DESC OFFSET 30\n   );\n\n  RETURN new_id;\nEND;\n$function$\n;\n\nCREATE OR REPLACE FUNCTION public.cron_create_schema_backup()\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO \'public\', \'pg_catalog\'\nAS $function$\nBEGIN\n  PERFORM public.create_schema_backup(\'auto\', NULL);\nEND;\n$function$\n;\n\nCREATE OR REPLACE FUNCTION public.export_schema_sql()\n RETURNS text\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO \'public\', \'pg_catalog\'\nAS $function$\nDECLARE\n  out_sql text := \'\';\n  r record;\n  cols text;\n  pk text;\n  policy_cmd text;\nBEGIN\n  -- Apenas admins\n  IF NOT public.has_role(auth.uid(), \'admin\') THEN\n    RAISE EXCEPTION \'forbidden\';\n  END IF;\n\n  out_sql := \'-- Schema dump (public) gerado em \' || now()::text || E\'\\n\';\n  out_sql := out_sql || E\'-- Apenas DDL. Não inclui dados.\\n\\n\';\n\n  -- 1) ENUMS\n  out_sql := out_sql || E\'-- =====================\\n-- ENUMS\\n-- =====================\\n\';\n  FOR r IN\n    SELECT n.nspname, t.typname,\n           string_agg(quote_literal(e.enumlabel), \', \' ORDER BY e.enumsortorder) AS labels\n    FROM pg_type t\n    JOIN pg_enum e ON e.enumtypid = t.oid\n    JOIN pg_namespace n ON n.oid = t.typnamespace\n    WHERE n.nspname = \'public\'\n    GROUP BY n.nspname, t.typname\n    ORDER BY t.typname\n  LOOP\n    out_sql := out_sql || format(E\'CREATE TYPE %I.%I AS ENUM (%s);\\n\', r.nspname, r.typname, r.labels);\n  END LOOP;\n  out_sql := out_sql || E\'\\n\';\n\n  -- 2) TABELAS + COLUNAS + PK\n  out_sql := out_sql || E\'-- =====================\\n-- TABELAS\\n-- =====================\\n\';\n  FOR r IN\n    SELECT c.oid, c.relname\n    FROM pg_class c\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname = \'public\' AND c.relkind = \'r\'\n    ORDER BY c.relname\n  LOOP\n    -- colunas\n    SELECT string_agg(\n      format(\'  %I %s%s%s\',\n        a.attname,\n        format_type(a.atttypid, a.atttypmod),\n        CASE WHEN a.attnotnull THEN \' NOT NULL\' ELSE \'\' END,\n        CASE WHEN ad.adbin IS NOT NULL\n             THEN \' DEFAULT \' || pg_get_expr(ad.adbin, ad.adrelid)\n             ELSE \'\' END\n      ), E\',\\n\' ORDER BY a.attnum\n    )\n    INTO cols\n    FROM pg_attribute a\n    LEFT JOIN pg_attrdef ad ON ad.adrelid = a.attrelid AND ad.adnum = a.attnum\n    WHERE a.attrelid = r.oid AND a.attnum > 0 AND NOT a.attisdropped;\n\n    -- PK\n    SELECT format(\',\\n  CONSTRAINT %I PRIMARY KEY (%s)\',\n      con.conname,\n      (SELECT string_agg(quote_ident(att.attname), \', \' ORDER BY array_position(con.conkey, att.attnum))\n         FROM pg_attribute att\n        WHERE att.attrelid = r.oid AND att.attnum = ANY(con.conkey)))\n    INTO pk\n    FROM pg_constraint con\n    WHERE con.conrelid = r.oid AND con.contype = \'p\'\n    LIMIT 1;\n\n    out_sql := out_sql || format(E\'\\nCREATE TABLE public.%I (\\n%s%s\\n);\\n\',\n      r.relname, cols, COALESCE(pk, \'\'));\n  END LOOP;\n\n  -- 3) FK / UNIQUE / CHECK constraints (separados, depois de todas as tabelas)\n  out_sql := out_sql || E\'\\n-- =====================\\n-- CONSTRAINTS (FK/UNIQUE/CHECK)\\n-- =====================\\n\';\n  FOR r IN\n    SELECT c.relname AS table_name, con.conname,\n           pg_get_constraintdef(con.oid) AS def\n    FROM pg_constraint con\n    JOIN pg_class c ON c.oid = con.conrelid\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname = \'public\' AND con.contype IN (\'f\',\'u\',\'c\')\n    ORDER BY c.relname, con.conname\n  LOOP\n    out_sql := out_sql || format(E\'ALTER TABLE public.%I ADD CONSTRAINT %I %s;\\n\',\n      r.table_name, r.conname, r.def);\n  END LOOP;\n\n  -- 4) ÍNDICES (não-PK / não-unique-constraint)\n  out_sql := out_sql || E\'\\n-- =====================\\n-- ÍNDICES\\n-- =====================\\n\';\n  FOR r IN\n    SELECT indexdef\n    FROM pg_indexes\n    WHERE schemaname = \'public\'\n      AND indexname NOT IN (\n        SELECT conname FROM pg_constraint WHERE contype IN (\'p\',\'u\')\n      )\n    ORDER BY tablename, indexname\n  LOOP\n    out_sql := out_sql || r.indexdef || E\';\\n\';\n  END LOOP;\n\n  -- 5) RLS + POLICIES\n  out_sql := out_sql || E\'\\n-- =====================\\n-- ROW LEVEL SECURITY\\n-- =====================\\n\';\n  FOR r IN\n    SELECT c.relname\n    FROM pg_class c\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname=\'public\' AND c.relkind=\'r\' AND c.relrowsecurity\n    ORDER BY c.relname\n  LOOP\n    out_sql := out_sql || format(E\'ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY;\\n\', r.relname);\n  END LOOP;\n\n  out_sql := out_sql || E\'\\n-- Policies\\n\';\n  FOR r IN\n    SELECT schemaname, tablename, policyname, permissive, roles, cmd, qual, with_check\n    FROM pg_policies\n    WHERE schemaname=\'public\'\n    ORDER BY tablename, policyname\n  LOOP\n    policy_cmd := format(\'CREATE POLICY %I ON public.%I AS %s FOR %s TO %s\',\n      r.policyname, r.tablename,\n      COALESCE(r.permissive,\'PERMISSIVE\'),\n      r.cmd,\n      array_to_string(r.roles, \', \'));\n    IF r.qual IS NOT NULL THEN\n      policy_cmd := policy_cmd || \' USING (\' || r.qual || \')\';\n    END IF;\n    IF r.with_check IS NOT NULL THEN\n      policy_cmd := policy_cmd || \' WITH CHECK (\' || r.with_check || \')\';\n    END IF;\n    out_sql := out_sql || policy_cmd || E\';\\n\';\n  END LOOP;\n\n  -- 6) FUNÇÕES\n  out_sql := out_sql || E\'\\n-- =====================\\n-- FUNÇÕES\\n-- =====================\\n\';\n  FOR r IN\n    SELECT pg_get_functiondef(p.oid) AS def\n    FROM pg_proc p\n    JOIN pg_namespace n ON n.oid = p.pronamespace\n    WHERE n.nspname=\'public\' AND p.prokind = \'f\'\n    ORDER BY p.proname\n  LOOP\n    out_sql := out_sql || r.def || E\';\\n\\n\';\n  END LOOP;\n\n  -- 7) TRIGGERS\n  out_sql := out_sql || E\'-- =====================\\n-- TRIGGERS\\n-- =====================\\n\';\n  FOR r IN\n    SELECT pg_get_triggerdef(t.oid) AS def\n    FROM pg_trigger t\n    JOIN pg_class c ON c.oid = t.tgrelid\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname=\'public\' AND NOT t.tgisinternal\n    ORDER BY c.relname, t.tgname\n  LOOP\n    out_sql := out_sql || r.def || E\';\\n\';\n  END LOOP;\n\n  RETURN out_sql;\nEND;\n$function$\n;\n\nCREATE OR REPLACE FUNCTION public.export_schema_sql_internal()\n RETURNS text\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO \'public\', \'pg_catalog\'\nAS $function$\nDECLARE\n  out_sql text := \'\';\n  r record;\n  cols text;\n  pk text;\n  policy_cmd text;\nBEGIN\n  out_sql := \'-- Schema dump (public) gerado em \' || now()::text || E\'\\n\';\n  out_sql := out_sql || E\'-- Apenas DDL. Não inclui dados.\\n\\n\';\n\n  out_sql := out_sql || E\'-- =====================\\n-- ENUMS\\n-- =====================\\n\';\n  FOR r IN\n    SELECT n.nspname, t.typname,\n           string_agg(quote_literal(e.enumlabel), \', \' ORDER BY e.enumsortorder) AS labels\n    FROM pg_type t\n    JOIN pg_enum e ON e.enumtypid = t.oid\n    JOIN pg_namespace n ON n.oid = t.typnamespace\n    WHERE n.nspname = \'public\'\n    GROUP BY n.nspname, t.typname\n    ORDER BY t.typname\n  LOOP\n    out_sql := out_sql || format(E\'CREATE TYPE %I.%I AS ENUM (%s);\\n\', r.nspname, r.typname, r.labels);\n  END LOOP;\n  out_sql := out_sql || E\'\\n\';\n\n  out_sql := out_sql || E\'-- =====================\\n-- TABELAS\\n-- =====================\\n\';\n  FOR r IN\n    SELECT c.oid, c.relname\n    FROM pg_class c\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname = \'public\' AND c.relkind = \'r\'\n    ORDER BY c.relname\n  LOOP\n    SELECT string_agg(\n      format(\'  %I %s%s%s\',\n        a.attname,\n        format_type(a.atttypid, a.atttypmod),\n        CASE WHEN a.attnotnull THEN \' NOT NULL\' ELSE \'\' END,\n        CASE WHEN ad.adbin IS NOT NULL\n             THEN \' DEFAULT \' || pg_get_expr(ad.adbin, ad.adrelid)\n             ELSE \'\' END\n      ), E\',\\n\' ORDER BY a.attnum\n    )\n    INTO cols\n    FROM pg_attribute a\n    LEFT JOIN pg_attrdef ad ON ad.adrelid = a.attrelid AND ad.adnum = a.attnum\n    WHERE a.attrelid = r.oid AND a.attnum > 0 AND NOT a.attisdropped;\n\n    SELECT format(\',\\n  CONSTRAINT %I PRIMARY KEY (%s)\',\n      con.conname,\n      (SELECT string_agg(quote_ident(att.attname), \', \' ORDER BY array_position(con.conkey, att.attnum))\n         FROM pg_attribute att\n        WHERE att.attrelid = r.oid AND att.attnum = ANY(con.conkey)))\n    INTO pk\n    FROM pg_constraint con\n    WHERE con.conrelid = r.oid AND con.contype = \'p\'\n    LIMIT 1;\n\n    out_sql := out_sql || format(E\'\\nCREATE TABLE public.%I (\\n%s%s\\n);\\n\',\n      r.relname, cols, COALESCE(pk, \'\'));\n  END LOOP;\n\n  out_sql := out_sql || E\'\\n-- =====================\\n-- CONSTRAINTS (FK/UNIQUE/CHECK)\\n-- =====================\\n\';\n  FOR r IN\n    SELECT c.relname AS table_name, con.conname,\n           pg_get_constraintdef(con.oid) AS def\n    FROM pg_constraint con\n    JOIN pg_class c ON c.oid = con.conrelid\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname = \'public\' AND con.contype IN (\'f\',\'u\',\'c\')\n    ORDER BY c.relname, con.conname\n  LOOP\n    out_sql := out_sql || format(E\'ALTER TABLE public.%I ADD CONSTRAINT %I %s;\\n\',\n      r.table_name, r.conname, r.def);\n  END LOOP;\n\n  out_sql := out_sql || E\'\\n-- =====================\\n-- ÍNDICES\\n-- =====================\\n\';\n  FOR r IN\n    SELECT indexdef\n    FROM pg_indexes\n    WHERE schemaname = \'public\'\n      AND indexname NOT IN (SELECT conname FROM pg_constraint WHERE contype IN (\'p\',\'u\'))\n    ORDER BY tablename, indexname\n  LOOP\n    out_sql := out_sql || r.indexdef || E\';\\n\';\n  END LOOP;\n\n  out_sql := out_sql || E\'\\n-- =====================\\n-- ROW LEVEL SECURITY\\n-- =====================\\n\';\n  FOR r IN\n    SELECT c.relname FROM pg_class c\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname=\'public\' AND c.relkind=\'r\' AND c.relrowsecurity\n    ORDER BY c.relname\n  LOOP\n    out_sql := out_sql || format(E\'ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY;\\n\', r.relname);\n  END LOOP;\n\n  out_sql := out_sql || E\'\\n-- Policies\\n\';\n  FOR r IN\n    SELECT schemaname, tablename, policyname, permissive, roles, cmd, qual, with_check\n    FROM pg_policies WHERE schemaname=\'public\' ORDER BY tablename, policyname\n  LOOP\n    policy_cmd := format(\'CREATE POLICY %I ON public.%I AS %s FOR %s TO %s\',\n      r.policyname, r.tablename, COALESCE(r.permissive,\'PERMISSIVE\'),\n      r.cmd, array_to_string(r.roles, \', \'));\n    IF r.qual IS NOT NULL THEN policy_cmd := policy_cmd || \' USING (\' || r.qual || \')\'; END IF;\n    IF r.with_check IS NOT NULL THEN policy_cmd := policy_cmd || \' WITH CHECK (\' || r.with_check || \')\'; END IF;\n    out_sql := out_sql || policy_cmd || E\';\\n\';\n  END LOOP;\n\n  out_sql := out_sql || E\'\\n-- =====================\\n-- FUNÇÕES\\n-- =====================\\n\';\n  FOR r IN\n    SELECT pg_get_functiondef(p.oid) AS def\n    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n    WHERE n.nspname=\'public\' AND p.prokind=\'f\' ORDER BY p.proname\n  LOOP\n    out_sql := out_sql || r.def || E\';\\n\\n\';\n  END LOOP;\n\n  out_sql := out_sql || E\'-- =====================\\n-- TRIGGERS\\n-- =====================\\n\';\n  FOR r IN\n    SELECT pg_get_triggerdef(t.oid) AS def\n    FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname=\'public\' AND NOT t.tgisinternal\n    ORDER BY c.relname, t.tgname\n  LOOP\n    out_sql := out_sql || r.def || E\';\\n\';\n  END LOOP;\n\n  RETURN out_sql;\nEND;\n$function$\n;\n\nCREATE OR REPLACE FUNCTION public.handle_new_user()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO \'public\'\nAS $function$\nbegin\n  insert into public.profiles (id, email, display_name)\n  values (new.id, new.email, coalesce(new.raw_user_meta_data->>\'display_name\', split_part(new.email,\'@\',1)));\n  return new;\nend;\n$function$\n;\n\nCREATE OR REPLACE FUNCTION public.has_role(_user_id uuid, _role app_role)\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO \'public\'\nAS $function$\n  SELECT EXISTS (\n    SELECT 1 FROM public.user_roles\n    WHERE user_id = _user_id AND role = _role\n  )\n$function$\n;\n\nCREATE OR REPLACE FUNCTION public.set_updated_at()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO \'public\'\nAS $function$\nbegin new.updated_at = now(); return new; end;\n$function$\n;\n\n-- =====================\n-- TRIGGERS\n-- =====================\nCREATE TRIGGER campaigns_updated BEFORE UPDATE ON public.campaigns FOR EACH ROW EXECUTE FUNCTION set_updated_at();\nCREATE TRIGGER contacts_updated BEFORE UPDATE ON public.contacts FOR EACH ROW EXECUTE FUNCTION set_updated_at();\nCREATE TRIGGER profiles_updated BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION set_updated_at();\n', 30645, '2026-05-29 03:00:00');
INSERT INTO `schema_backups` (`id`, `created_by`, `source`, `sql`, `size_bytes`, `created_at`) VALUES
('6e59fdea-3c3b-4d18-b56e-1185f8ecab03', NULL, 'auto', '-- Schema dump (public) gerado em 2026-06-06 03:00:00.024553+00\n-- Apenas DDL. Não inclui dados.\n\n-- =====================\n-- ENUMS\n-- =====================\nCREATE TYPE public.app_role AS ENUM (\'admin\', \'user\');\nCREATE TYPE public.campaign_status AS ENUM (\'draft\', \'queued\', \'running\', \'done\', \'failed\', \'cancelled\');\nCREATE TYPE public.message_status AS ENUM (\'pending\', \'sending\', \'sent\', \'delivered\', \'read\', \'failed\');\nCREATE TYPE public.message_type AS ENUM (\'template\', \'text\', \'media\', \'interactive\');\nCREATE TYPE public.template_status AS ENUM (\'APPROVED\', \'PENDING\', \'REJECTED\', \'PAUSED\', \'DISABLED\');\n\n-- =====================\n-- TABELAS\n-- =====================\n\nCREATE TABLE public.audit_logs (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid,\n  actor_email text,\n  action text NOT NULL,\n  entity_type text,\n  entity_id text,\n  metadata jsonb NOT NULL DEFAULT \'{}\'::jsonb,\n  ip text,\n  user_agent text,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT audit_logs_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.campaign_messages (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL,\n  campaign_id uuid NOT NULL,\n  contact_id uuid,\n  to_phone text NOT NULL,\n  status message_status NOT NULL DEFAULT \'pending\'::message_status,\n  wa_message_id text,\n  error jsonb,\n  attempts integer NOT NULL DEFAULT 0,\n  sent_at timestamp with time zone,\n  delivered_at timestamp with time zone,\n  read_at timestamp with time zone,\n  failed_at timestamp with time zone,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\n  pricing_billable boolean,\n  pricing_category text,\n  pricing_model text,\n  conversation_id text,\n  conversation_origin text,\\n  CONSTRAINT campaign_messages_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.campaigns (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL,\n  name text NOT NULL,\n  message_type message_type NOT NULL,\n  template_id uuid,\n  list_id uuid,\n  payload jsonb NOT NULL DEFAULT \'{}\'::jsonb,\n  status campaign_status NOT NULL DEFAULT \'draft\'::campaign_status,\n  scheduled_at timestamp with time zone,\n  started_at timestamp with time zone,\n  finished_at timestamp with time zone,\n  totals jsonb NOT NULL DEFAULT \'{\"read\": 0, \"sent\": 0, \"total\": 0, \"failed\": 0, \"pending\": 0, \"delivered\": 0}\'::jsonb,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\n  updated_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT campaigns_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.contact_tags (\n  contact_id uuid NOT NULL,\n  tag_id uuid NOT NULL,\n  user_id uuid NOT NULL,\\n  CONSTRAINT contact_tags_pkey PRIMARY KEY (contact_id, tag_id)\n);\n\nCREATE TABLE public.contacts (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL,\n  phone_e164 text NOT NULL,\n  name text,\n  email text,\n  custom_fields jsonb NOT NULL DEFAULT \'{}\'::jsonb,\n  opted_out boolean NOT NULL DEFAULT false,\n  source text,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\n  updated_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT contacts_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.list_contacts (\n  list_id uuid NOT NULL,\n  contact_id uuid NOT NULL,\n  user_id uuid NOT NULL,\n  added_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT list_contacts_pkey PRIMARY KEY (list_id, contact_id)\n);\n\nCREATE TABLE public.lists (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL,\n  name text NOT NULL,\n  description text,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT lists_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.platform_settings (\n  id smallint NOT NULL DEFAULT 1,\n  meta_app_id text,\n  meta_app_secret text,\n  meta_config_id text,\n  meta_graph_version text NOT NULL DEFAULT \'v20.0\'::text,\n  updated_at timestamp with time zone NOT NULL DEFAULT now(),\n  updated_by uuid,\n  head_tags text,\n  body_tags text,\n  cron_secret text,\\n  CONSTRAINT platform_settings_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.profiles (\n  id uuid NOT NULL,\n  display_name text,\n  email text,\n  whatsapp_phone_number_id text,\n  whatsapp_waba_id text,\n  whatsapp_business_phone text,\n  api_key text NOT NULL DEFAULT encode(extensions.gen_random_bytes(24), \'hex\'::text),\n  rate_limit_per_second integer NOT NULL DEFAULT 20,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\n  updated_at timestamp with time zone NOT NULL DEFAULT now(),\n  whatsapp_access_token text,\n  whatsapp_app_secret text,\n  whatsapp_verify_token text,\n  meta_graph_version text NOT NULL DEFAULT \'v20.0\'::text,\n  avatar_url text,\n  full_name text,\n  phone text,\n  company_name text,\n  company_document text,\n  company_website text,\n  company_address text,\\n  CONSTRAINT profiles_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.schema_backups (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\n  source text NOT NULL DEFAULT \'auto\'::text,\n  size_bytes integer NOT NULL DEFAULT 0,\n  sql text NOT NULL,\n  created_by uuid,\\n  CONSTRAINT schema_backups_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.tags (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL,\n  name text NOT NULL,\n  color text NOT NULL DEFAULT \'#25D366\'::text,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT tags_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.templates (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL,\n  meta_template_id text,\n  name text NOT NULL,\n  language text NOT NULL,\n  category text,\n  status template_status NOT NULL DEFAULT \'PENDING\'::template_status,\n  components jsonb NOT NULL DEFAULT \'[]\'::jsonb,\n  synced_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT templates_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.user_roles (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL,\n  role app_role NOT NULL,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\\n  CONSTRAINT user_roles_pkey PRIMARY KEY (id)\n);\n\nCREATE TABLE public.webhook_events (\n  id uuid NOT NULL DEFAULT gen_random_uuid(),\n  source text NOT NULL DEFAULT \'whatsapp\'::text,\n  raw jsonb NOT NULL,\n  processed boolean NOT NULL DEFAULT false,\n  received_at timestamp with time zone NOT NULL DEFAULT now(),\n  user_id uuid,\\n  CONSTRAINT webhook_events_pkey PRIMARY KEY (id)\n);\n\n-- =====================\n-- CONSTRAINTS (FK/UNIQUE/CHECK)\n-- =====================\nALTER TABLE public.audit_logs ADD CONSTRAINT audit_logs_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE SET NULL;\nALTER TABLE public.campaign_messages ADD CONSTRAINT campaign_messages_campaign_id_fkey FOREIGN KEY (campaign_id) REFERENCES campaigns(id) ON DELETE CASCADE;\nALTER TABLE public.campaign_messages ADD CONSTRAINT campaign_messages_contact_id_fkey FOREIGN KEY (contact_id) REFERENCES contacts(id) ON DELETE SET NULL;\nALTER TABLE public.campaign_messages ADD CONSTRAINT campaign_messages_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.campaigns ADD CONSTRAINT campaigns_list_id_fkey FOREIGN KEY (list_id) REFERENCES lists(id) ON DELETE SET NULL;\nALTER TABLE public.campaigns ADD CONSTRAINT campaigns_template_id_fkey FOREIGN KEY (template_id) REFERENCES templates(id) ON DELETE SET NULL;\nALTER TABLE public.campaigns ADD CONSTRAINT campaigns_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.contact_tags ADD CONSTRAINT contact_tags_contact_id_fkey FOREIGN KEY (contact_id) REFERENCES contacts(id) ON DELETE CASCADE;\nALTER TABLE public.contact_tags ADD CONSTRAINT contact_tags_tag_id_fkey FOREIGN KEY (tag_id) REFERENCES tags(id) ON DELETE CASCADE;\nALTER TABLE public.contact_tags ADD CONSTRAINT contact_tags_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.contacts ADD CONSTRAINT contacts_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.contacts ADD CONSTRAINT contacts_user_id_phone_e164_key UNIQUE (user_id, phone_e164);\nALTER TABLE public.list_contacts ADD CONSTRAINT list_contacts_contact_id_fkey FOREIGN KEY (contact_id) REFERENCES contacts(id) ON DELETE CASCADE;\nALTER TABLE public.list_contacts ADD CONSTRAINT list_contacts_list_id_fkey FOREIGN KEY (list_id) REFERENCES lists(id) ON DELETE CASCADE;\nALTER TABLE public.list_contacts ADD CONSTRAINT list_contacts_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.lists ADD CONSTRAINT lists_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.platform_settings ADD CONSTRAINT platform_settings_id_check CHECK ((id = 1));\nALTER TABLE public.platform_settings ADD CONSTRAINT platform_settings_updated_by_fkey FOREIGN KEY (updated_by) REFERENCES auth.users(id) ON DELETE SET NULL;\nALTER TABLE public.profiles ADD CONSTRAINT profiles_api_key_key UNIQUE (api_key);\nALTER TABLE public.profiles ADD CONSTRAINT profiles_id_fkey FOREIGN KEY (id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.tags ADD CONSTRAINT tags_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.tags ADD CONSTRAINT tags_user_id_name_key UNIQUE (user_id, name);\nALTER TABLE public.templates ADD CONSTRAINT templates_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.templates ADD CONSTRAINT templates_user_id_name_language_key UNIQUE (user_id, name, language);\nALTER TABLE public.user_roles ADD CONSTRAINT user_roles_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;\nALTER TABLE public.user_roles ADD CONSTRAINT user_roles_user_id_role_key UNIQUE (user_id, role);\n\n-- =====================\n-- ÍNDICES\n-- =====================\nCREATE INDEX audit_logs_action_idx ON public.audit_logs USING btree (action);\nCREATE INDEX audit_logs_created_idx ON public.audit_logs USING btree (created_at DESC);\nCREATE INDEX audit_logs_user_idx ON public.audit_logs USING btree (user_id, created_at DESC);\nCREATE INDEX cm_pending_idx ON public.campaign_messages USING btree (campaign_id, status);\nCREATE INDEX cm_user_idx ON public.campaign_messages USING btree (user_id, status);\nCREATE INDEX cm_wa_id_idx ON public.campaign_messages USING btree (wa_message_id);\nCREATE INDEX idx_campaign_messages_billing ON public.campaign_messages USING btree (user_id, created_at DESC, pricing_category);\nCREATE INDEX idx_campaign_messages_status_updated ON public.campaign_messages USING btree (status, sent_at);\nCREATE INDEX contacts_user_idx ON public.contacts USING btree (user_id);\nCREATE INDEX list_contacts_list_idx ON public.list_contacts USING btree (list_id);\nCREATE INDEX idx_schema_backups_created_at ON public.schema_backups USING btree (created_at DESC);\nCREATE INDEX idx_webhook_events_received_at ON public.webhook_events USING btree (received_at);\nCREATE INDEX webhook_events_user_id_received_at_idx ON public.webhook_events USING btree (user_id, received_at DESC);\n\n-- =====================\n-- ROW LEVEL SECURITY\n-- =====================\nALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.campaign_messages ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.campaigns ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.contact_tags ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.contacts ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.list_contacts ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.lists ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.platform_settings ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.schema_backups ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.tags ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.templates ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.webhook_events ENABLE ROW LEVEL SECURITY;\n\n-- Policies\nCREATE POLICY audit_logs_no_delete ON public.audit_logs AS RESTRICTIVE FOR DELETE TO anon, authenticated USING (false);\nCREATE POLICY audit_logs_no_update ON public.audit_logs AS RESTRICTIVE FOR UPDATE TO anon, authenticated USING (false);\nCREATE POLICY audit_logs_no_write ON public.audit_logs AS RESTRICTIVE FOR INSERT TO anon, authenticated WITH CHECK (false);\nCREATE POLICY audit_logs_select_own_or_admin ON public.audit_logs AS PERMISSIVE FOR SELECT TO authenticated USING (((auth.uid() = user_id) OR has_role(auth.uid(), \'admin\'::app_role)));\nCREATE POLICY cm_delete_own ON public.campaign_messages AS PERMISSIVE FOR DELETE TO authenticated USING ((auth.uid() = user_id));\nCREATE POLICY cm_insert_own ON public.campaign_messages AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY cm_select_own ON public.campaign_messages AS PERMISSIVE FOR SELECT TO authenticated USING ((auth.uid() = user_id));\nCREATE POLICY cm_update_own ON public.campaign_messages AS PERMISSIVE FOR UPDATE TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY campaigns_all_own ON public.campaigns AS PERMISSIVE FOR ALL TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY contact_tags_all_own ON public.contact_tags AS PERMISSIVE FOR ALL TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY contacts_all_own ON public.contacts AS PERMISSIVE FOR ALL TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY list_contacts_all_own ON public.list_contacts AS PERMISSIVE FOR ALL TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY lists_all_own ON public.lists AS PERMISSIVE FOR ALL TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY platform_settings_admin_select ON public.platform_settings AS PERMISSIVE FOR SELECT TO authenticated USING (has_role(auth.uid(), \'admin\'::app_role));\nCREATE POLICY platform_settings_admin_update ON public.platform_settings AS PERMISSIVE FOR UPDATE TO authenticated USING (has_role(auth.uid(), \'admin\'::app_role)) WITH CHECK (has_role(auth.uid(), \'admin\'::app_role));\nCREATE POLICY profiles_insert_own ON public.profiles AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK ((auth.uid() = id));\nCREATE POLICY profiles_select_own ON public.profiles AS PERMISSIVE FOR SELECT TO authenticated USING ((auth.uid() = id));\nCREATE POLICY profiles_update_own ON public.profiles AS PERMISSIVE FOR UPDATE TO authenticated USING ((auth.uid() = id)) WITH CHECK ((auth.uid() = id));\nCREATE POLICY schema_backups_admin_delete ON public.schema_backups AS PERMISSIVE FOR DELETE TO authenticated USING (has_role(auth.uid(), \'admin\'::app_role));\nCREATE POLICY schema_backups_admin_insert ON public.schema_backups AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK (has_role(auth.uid(), \'admin\'::app_role));\nCREATE POLICY schema_backups_admin_select ON public.schema_backups AS PERMISSIVE FOR SELECT TO authenticated USING (has_role(auth.uid(), \'admin\'::app_role));\nCREATE POLICY tags_all_own ON public.tags AS PERMISSIVE FOR ALL TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY templates_all_own ON public.templates AS PERMISSIVE FOR ALL TO authenticated USING ((auth.uid() = user_id)) WITH CHECK ((auth.uid() = user_id));\nCREATE POLICY user_roles_admin_manage ON public.user_roles AS PERMISSIVE FOR ALL TO authenticated USING (has_role(auth.uid(), \'admin\'::app_role)) WITH CHECK (has_role(auth.uid(), \'admin\'::app_role));\nCREATE POLICY user_roles_block_self_delete ON public.user_roles AS RESTRICTIVE FOR DELETE TO authenticated USING ((user_id <> auth.uid()));\nCREATE POLICY user_roles_block_self_insert ON public.user_roles AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK ((user_id <> auth.uid()));\nCREATE POLICY user_roles_block_self_update ON public.user_roles AS RESTRICTIVE FOR UPDATE TO authenticated USING ((user_id <> auth.uid())) WITH CHECK ((user_id <> auth.uid()));\nCREATE POLICY user_roles_select_own ON public.user_roles AS PERMISSIVE FOR SELECT TO authenticated USING (((auth.uid() = user_id) OR has_role(auth.uid(), \'admin\'::app_role)));\nCREATE POLICY webhook_events_no_delete ON public.webhook_events AS RESTRICTIVE FOR DELETE TO anon, authenticated USING (false);\nCREATE POLICY webhook_events_no_insert ON public.webhook_events AS RESTRICTIVE FOR INSERT TO anon, authenticated WITH CHECK (false);\nCREATE POLICY webhook_events_no_update ON public.webhook_events AS RESTRICTIVE FOR UPDATE TO anon, authenticated USING (false) WITH CHECK (false);\nCREATE POLICY webhook_events_select_own ON public.webhook_events AS PERMISSIVE FOR SELECT TO authenticated USING ((auth.uid() = user_id));\n\n-- =====================\n-- FUNÇÕES\n-- =====================\nCREATE OR REPLACE FUNCTION public.assign_default_role()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO \'public\'\nAS $function$\nDECLARE\n  has_any_admin boolean;\nBEGIN\n  SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE role = \'admin\') INTO has_any_admin;\n  IF NOT has_any_admin THEN\n    INSERT INTO public.user_roles (user_id, role) VALUES (NEW.id, \'admin\')\n      ON CONFLICT DO NOTHING;\n  ELSE\n    INSERT INTO public.user_roles (user_id, role) VALUES (NEW.id, \'user\')\n      ON CONFLICT DO NOTHING;\n  END IF;\n  RETURN NEW;\nEND;\n$function$\n;\n\nCREATE OR REPLACE FUNCTION public.create_schema_backup(_source text DEFAULT \'auto\'::text, _user uuid DEFAULT NULL::uuid)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO \'public\', \'pg_catalog\'\nAS $function$\nDECLARE\n  dump text;\n  new_id uuid;\nBEGIN\n  -- Gera o dump (a função export_schema_sql exige admin; aqui contornamos por se rodar via cron/service_role)\n  -- Por isso replicamos a chamada interna como SECURITY DEFINER e pulamos o has_role quando _user é NULL (cron).\n  IF _user IS NOT NULL AND NOT public.has_role(_user, \'admin\') THEN\n    RAISE EXCEPTION \'forbidden\';\n  END IF;\n\n  -- Chama a função existente como superuser deste DEFINER\n  EXECUTE \'SELECT public.export_schema_sql_internal()\' INTO dump;\n\n  INSERT INTO public.schema_backups (source, size_bytes, sql, created_by)\n  VALUES (COALESCE(_source, \'auto\'), COALESCE(length(dump), 0), COALESCE(dump, \'\'), _user)\n  RETURNING id INTO new_id;\n\n  -- Mantém apenas as 30 versões mais recentes\n  DELETE FROM public.schema_backups\n   WHERE id IN (\n     SELECT id FROM public.schema_backups\n      ORDER BY created_at DESC OFFSET 30\n   );\n\n  RETURN new_id;\nEND;\n$function$\n;\n\nCREATE OR REPLACE FUNCTION public.cron_create_schema_backup()\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO \'public\', \'pg_catalog\'\nAS $function$\nBEGIN\n  PERFORM public.create_schema_backup(\'auto\', NULL);\nEND;\n$function$\n;\n\nCREATE OR REPLACE FUNCTION public.export_schema_sql()\n RETURNS text\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO \'public\', \'pg_catalog\'\nAS $function$\nDECLARE\n  out_sql text := \'\';\n  r record;\n  cols text;\n  pk text;\n  policy_cmd text;\nBEGIN\n  -- Apenas admins\n  IF NOT public.has_role(auth.uid(), \'admin\') THEN\n    RAISE EXCEPTION \'forbidden\';\n  END IF;\n\n  out_sql := \'-- Schema dump (public) gerado em \' || now()::text || E\'\\n\';\n  out_sql := out_sql || E\'-- Apenas DDL. Não inclui dados.\\n\\n\';\n\n  -- 1) ENUMS\n  out_sql := out_sql || E\'-- =====================\\n-- ENUMS\\n-- =====================\\n\';\n  FOR r IN\n    SELECT n.nspname, t.typname,\n           string_agg(quote_literal(e.enumlabel), \', \' ORDER BY e.enumsortorder) AS labels\n    FROM pg_type t\n    JOIN pg_enum e ON e.enumtypid = t.oid\n    JOIN pg_namespace n ON n.oid = t.typnamespace\n    WHERE n.nspname = \'public\'\n    GROUP BY n.nspname, t.typname\n    ORDER BY t.typname\n  LOOP\n    out_sql := out_sql || format(E\'CREATE TYPE %I.%I AS ENUM (%s);\\n\', r.nspname, r.typname, r.labels);\n  END LOOP;\n  out_sql := out_sql || E\'\\n\';\n\n  -- 2) TABELAS + COLUNAS + PK\n  out_sql := out_sql || E\'-- =====================\\n-- TABELAS\\n-- =====================\\n\';\n  FOR r IN\n    SELECT c.oid, c.relname\n    FROM pg_class c\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname = \'public\' AND c.relkind = \'r\'\n    ORDER BY c.relname\n  LOOP\n    -- colunas\n    SELECT string_agg(\n      format(\'  %I %s%s%s\',\n        a.attname,\n        format_type(a.atttypid, a.atttypmod),\n        CASE WHEN a.attnotnull THEN \' NOT NULL\' ELSE \'\' END,\n        CASE WHEN ad.adbin IS NOT NULL\n             THEN \' DEFAULT \' || pg_get_expr(ad.adbin, ad.adrelid)\n             ELSE \'\' END\n      ), E\',\\n\' ORDER BY a.attnum\n    )\n    INTO cols\n    FROM pg_attribute a\n    LEFT JOIN pg_attrdef ad ON ad.adrelid = a.attrelid AND ad.adnum = a.attnum\n    WHERE a.attrelid = r.oid AND a.attnum > 0 AND NOT a.attisdropped;\n\n    -- PK\n    SELECT format(\',\\n  CONSTRAINT %I PRIMARY KEY (%s)\',\n      con.conname,\n      (SELECT string_agg(quote_ident(att.attname), \', \' ORDER BY array_position(con.conkey, att.attnum))\n         FROM pg_attribute att\n        WHERE att.attrelid = r.oid AND att.attnum = ANY(con.conkey)))\n    INTO pk\n    FROM pg_constraint con\n    WHERE con.conrelid = r.oid AND con.contype = \'p\'\n    LIMIT 1;\n\n    out_sql := out_sql || format(E\'\\nCREATE TABLE public.%I (\\n%s%s\\n);\\n\',\n      r.relname, cols, COALESCE(pk, \'\'));\n  END LOOP;\n\n  -- 3) FK / UNIQUE / CHECK constraints (separados, depois de todas as tabelas)\n  out_sql := out_sql || E\'\\n-- =====================\\n-- CONSTRAINTS (FK/UNIQUE/CHECK)\\n-- =====================\\n\';\n  FOR r IN\n    SELECT c.relname AS table_name, con.conname,\n           pg_get_constraintdef(con.oid) AS def\n    FROM pg_constraint con\n    JOIN pg_class c ON c.oid = con.conrelid\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname = \'public\' AND con.contype IN (\'f\',\'u\',\'c\')\n    ORDER BY c.relname, con.conname\n  LOOP\n    out_sql := out_sql || format(E\'ALTER TABLE public.%I ADD CONSTRAINT %I %s;\\n\',\n      r.table_name, r.conname, r.def);\n  END LOOP;\n\n  -- 4) ÍNDICES (não-PK / não-unique-constraint)\n  out_sql := out_sql || E\'\\n-- =====================\\n-- ÍNDICES\\n-- =====================\\n\';\n  FOR r IN\n    SELECT indexdef\n    FROM pg_indexes\n    WHERE schemaname = \'public\'\n      AND indexname NOT IN (\n        SELECT conname FROM pg_constraint WHERE contype IN (\'p\',\'u\')\n      )\n    ORDER BY tablename, indexname\n  LOOP\n    out_sql := out_sql || r.indexdef || E\';\\n\';\n  END LOOP;\n\n  -- 5) RLS + POLICIES\n  out_sql := out_sql || E\'\\n-- =====================\\n-- ROW LEVEL SECURITY\\n-- =====================\\n\';\n  FOR r IN\n    SELECT c.relname\n    FROM pg_class c\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname=\'public\' AND c.relkind=\'r\' AND c.relrowsecurity\n    ORDER BY c.relname\n  LOOP\n    out_sql := out_sql || format(E\'ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY;\\n\', r.relname);\n  END LOOP;\n\n  out_sql := out_sql || E\'\\n-- Policies\\n\';\n  FOR r IN\n    SELECT schemaname, tablename, policyname, permissive, roles, cmd, qual, with_check\n    FROM pg_policies\n    WHERE schemaname=\'public\'\n    ORDER BY tablename, policyname\n  LOOP\n    policy_cmd := format(\'CREATE POLICY %I ON public.%I AS %s FOR %s TO %s\',\n      r.policyname, r.tablename,\n      COALESCE(r.permissive,\'PERMISSIVE\'),\n      r.cmd,\n      array_to_string(r.roles, \', \'));\n    IF r.qual IS NOT NULL THEN\n      policy_cmd := policy_cmd || \' USING (\' || r.qual || \')\';\n    END IF;\n    IF r.with_check IS NOT NULL THEN\n      policy_cmd := policy_cmd || \' WITH CHECK (\' || r.with_check || \')\';\n    END IF;\n    out_sql := out_sql || policy_cmd || E\';\\n\';\n  END LOOP;\n\n  -- 6) FUNÇÕES\n  out_sql := out_sql || E\'\\n-- =====================\\n-- FUNÇÕES\\n-- =====================\\n\';\n  FOR r IN\n    SELECT pg_get_functiondef(p.oid) AS def\n    FROM pg_proc p\n    JOIN pg_namespace n ON n.oid = p.pronamespace\n    WHERE n.nspname=\'public\' AND p.prokind = \'f\'\n    ORDER BY p.proname\n  LOOP\n    out_sql := out_sql || r.def || E\';\\n\\n\';\n  END LOOP;\n\n  -- 7) TRIGGERS\n  out_sql := out_sql || E\'-- =====================\\n-- TRIGGERS\\n-- =====================\\n\';\n  FOR r IN\n    SELECT pg_get_triggerdef(t.oid) AS def\n    FROM pg_trigger t\n    JOIN pg_class c ON c.oid = t.tgrelid\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname=\'public\' AND NOT t.tgisinternal\n    ORDER BY c.relname, t.tgname\n  LOOP\n    out_sql := out_sql || r.def || E\';\\n\';\n  END LOOP;\n\n  RETURN out_sql;\nEND;\n$function$\n;\n\nCREATE OR REPLACE FUNCTION public.export_schema_sql_internal()\n RETURNS text\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO \'public\', \'pg_catalog\'\nAS $function$\nDECLARE\n  out_sql text := \'\';\n  r record;\n  cols text;\n  pk text;\n  policy_cmd text;\nBEGIN\n  out_sql := \'-- Schema dump (public) gerado em \' || now()::text || E\'\\n\';\n  out_sql := out_sql || E\'-- Apenas DDL. Não inclui dados.\\n\\n\';\n\n  out_sql := out_sql || E\'-- =====================\\n-- ENUMS\\n-- =====================\\n\';\n  FOR r IN\n    SELECT n.nspname, t.typname,\n           string_agg(quote_literal(e.enumlabel), \', \' ORDER BY e.enumsortorder) AS labels\n    FROM pg_type t\n    JOIN pg_enum e ON e.enumtypid = t.oid\n    JOIN pg_namespace n ON n.oid = t.typnamespace\n    WHERE n.nspname = \'public\'\n    GROUP BY n.nspname, t.typname\n    ORDER BY t.typname\n  LOOP\n    out_sql := out_sql || format(E\'CREATE TYPE %I.%I AS ENUM (%s);\\n\', r.nspname, r.typname, r.labels);\n  END LOOP;\n  out_sql := out_sql || E\'\\n\';\n\n  out_sql := out_sql || E\'-- =====================\\n-- TABELAS\\n-- =====================\\n\';\n  FOR r IN\n    SELECT c.oid, c.relname\n    FROM pg_class c\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname = \'public\' AND c.relkind = \'r\'\n    ORDER BY c.relname\n  LOOP\n    SELECT string_agg(\n      format(\'  %I %s%s%s\',\n        a.attname,\n        format_type(a.atttypid, a.atttypmod),\n        CASE WHEN a.attnotnull THEN \' NOT NULL\' ELSE \'\' END,\n        CASE WHEN ad.adbin IS NOT NULL\n             THEN \' DEFAULT \' || pg_get_expr(ad.adbin, ad.adrelid)\n             ELSE \'\' END\n      ), E\',\\n\' ORDER BY a.attnum\n    )\n    INTO cols\n    FROM pg_attribute a\n    LEFT JOIN pg_attrdef ad ON ad.adrelid = a.attrelid AND ad.adnum = a.attnum\n    WHERE a.attrelid = r.oid AND a.attnum > 0 AND NOT a.attisdropped;\n\n    SELECT format(\',\\n  CONSTRAINT %I PRIMARY KEY (%s)\',\n      con.conname,\n      (SELECT string_agg(quote_ident(att.attname), \', \' ORDER BY array_position(con.conkey, att.attnum))\n         FROM pg_attribute att\n        WHERE att.attrelid = r.oid AND att.attnum = ANY(con.conkey)))\n    INTO pk\n    FROM pg_constraint con\n    WHERE con.conrelid = r.oid AND con.contype = \'p\'\n    LIMIT 1;\n\n    out_sql := out_sql || format(E\'\\nCREATE TABLE public.%I (\\n%s%s\\n);\\n\',\n      r.relname, cols, COALESCE(pk, \'\'));\n  END LOOP;\n\n  out_sql := out_sql || E\'\\n-- =====================\\n-- CONSTRAINTS (FK/UNIQUE/CHECK)\\n-- =====================\\n\';\n  FOR r IN\n    SELECT c.relname AS table_name, con.conname,\n           pg_get_constraintdef(con.oid) AS def\n    FROM pg_constraint con\n    JOIN pg_class c ON c.oid = con.conrelid\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname = \'public\' AND con.contype IN (\'f\',\'u\',\'c\')\n    ORDER BY c.relname, con.conname\n  LOOP\n    out_sql := out_sql || format(E\'ALTER TABLE public.%I ADD CONSTRAINT %I %s;\\n\',\n      r.table_name, r.conname, r.def);\n  END LOOP;\n\n  out_sql := out_sql || E\'\\n-- =====================\\n-- ÍNDICES\\n-- =====================\\n\';\n  FOR r IN\n    SELECT indexdef\n    FROM pg_indexes\n    WHERE schemaname = \'public\'\n      AND indexname NOT IN (SELECT conname FROM pg_constraint WHERE contype IN (\'p\',\'u\'))\n    ORDER BY tablename, indexname\n  LOOP\n    out_sql := out_sql || r.indexdef || E\';\\n\';\n  END LOOP;\n\n  out_sql := out_sql || E\'\\n-- =====================\\n-- ROW LEVEL SECURITY\\n-- =====================\\n\';\n  FOR r IN\n    SELECT c.relname FROM pg_class c\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname=\'public\' AND c.relkind=\'r\' AND c.relrowsecurity\n    ORDER BY c.relname\n  LOOP\n    out_sql := out_sql || format(E\'ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY;\\n\', r.relname);\n  END LOOP;\n\n  out_sql := out_sql || E\'\\n-- Policies\\n\';\n  FOR r IN\n    SELECT schemaname, tablename, policyname, permissive, roles, cmd, qual, with_check\n    FROM pg_policies WHERE schemaname=\'public\' ORDER BY tablename, policyname\n  LOOP\n    policy_cmd := format(\'CREATE POLICY %I ON public.%I AS %s FOR %s TO %s\',\n      r.policyname, r.tablename, COALESCE(r.permissive,\'PERMISSIVE\'),\n      r.cmd, array_to_string(r.roles, \', \'));\n    IF r.qual IS NOT NULL THEN policy_cmd := policy_cmd || \' USING (\' || r.qual || \')\'; END IF;\n    IF r.with_check IS NOT NULL THEN policy_cmd := policy_cmd || \' WITH CHECK (\' || r.with_check || \')\'; END IF;\n    out_sql := out_sql || policy_cmd || E\';\\n\';\n  END LOOP;\n\n  out_sql := out_sql || E\'\\n-- =====================\\n-- FUNÇÕES\\n-- =====================\\n\';\n  FOR r IN\n    SELECT pg_get_functiondef(p.oid) AS def\n    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace\n    WHERE n.nspname=\'public\' AND p.prokind=\'f\' ORDER BY p.proname\n  LOOP\n    out_sql := out_sql || r.def || E\';\\n\\n\';\n  END LOOP;\n\n  out_sql := out_sql || E\'-- =====================\\n-- TRIGGERS\\n-- =====================\\n\';\n  FOR r IN\n    SELECT pg_get_triggerdef(t.oid) AS def\n    FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid\n    JOIN pg_namespace n ON n.oid = c.relnamespace\n    WHERE n.nspname=\'public\' AND NOT t.tgisinternal\n    ORDER BY c.relname, t.tgname\n  LOOP\n    out_sql := out_sql || r.def || E\';\\n\';\n  END LOOP;\n\n  RETURN out_sql;\nEND;\n$function$\n;\n\nCREATE OR REPLACE FUNCTION public.handle_new_user()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO \'public\'\nAS $function$\nbegin\n  insert into public.profiles (id, email, display_name)\n  values (new.id, new.email, coalesce(new.raw_user_meta_data->>\'display_name\', split_part(new.email,\'@\',1)));\n  return new;\nend;\n$function$\n;\n\nCREATE OR REPLACE FUNCTION public.has_role(_user_id uuid, _role app_role)\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO \'public\'\nAS $function$\n  SELECT EXISTS (\n    SELECT 1 FROM public.user_roles\n    WHERE user_id = _user_id AND role = _role\n  )\n$function$\n;\n\nCREATE OR REPLACE FUNCTION public.set_updated_at()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO \'public\'\nAS $function$\nbegin new.updated_at = now(); return new; end;\n$function$\n;\n\n-- =====================\n-- TRIGGERS\n-- =====================\nCREATE TRIGGER campaigns_updated BEFORE UPDATE ON public.campaigns FOR EACH ROW EXECUTE FUNCTION set_updated_at();\nCREATE TRIGGER contacts_updated BEFORE UPDATE ON public.contacts FOR EACH ROW EXECUTE FUNCTION set_updated_at();\nCREATE TRIGGER profiles_updated BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION set_updated_at();\n', 30910, '2026-06-06 03:00:00');
